import Axios from "axios";
import { mainUrl } from "../../api/api";
import { config } from "../../api/api";
import moment from "moment";

// startDate: start !== "now" ? start : "",
//     endDate: end !== "now" ? end : "",
//     filterCompany:"",
//     userType: user_type ?? null,
//     userId: user_id ?? null,
//     detailType: detail_type ?? null,
//     isReady: user_id && user_type && detail_type ? true : false
export const reportApiLeads = async ({searchState}) => {
    const isTypeUser = await localStorage.getItem("user_type_leads_filter");
    const isChannels = await localStorage.getItem("channels_leads_filter");
    const checkChannels = isChannels === undefined || isChannels === null ? true : false
    return Axios.get(
        `${mainUrl}/dashboard/report-leads/hot-new?start_date=${
            searchState.startDate ? moment(searchState.startDate).format("YYYY-MM-DD") : ""
        }&end_date=${
            searchState.endDate ? moment(searchState.endDate).format("YYYY-MM-DD") : ""
        }&company_id=${searchState.filterCompany ? searchState.filterCompany : ""}&${
          isTypeUser === "sales"
          ?"sales_id=" + parseInt(searchState.userId ?? "")
          : isTypeUser === "store"
            ? "channel_id=" + parseInt(searchState.userId ?? "")
            : "supervisor_id=" + parseInt(searchState.userId ?? "")
        }&status=${searchState?.detailType?.toUpperCase()}&perPage=100`,
        config
      ).then((result) => result?.data)
        .catch((error) => error);
}