import React, { useEffect, useState } from 'react';
import { Connect } from 'react-redux';
import Axios from 'axios';
import LoadedComponent from '../../../../components/Loaded/LoadedComponent';
import moment from 'moment'
import { mainUrl } from '../../../../api/api';
import { useHistory } from 'react-router-dom';
import { MyFilters } from '../../../../componentsReuse';
import Button from '../../../../components/Button/Button';
const NewLeadsSeeDetails = () => {
    const history = useHistory();
    const stateHistory = history?.location?.state
    const [isData, setIsData] = useState([]);
    const [isLoading, setIsLoading] = useState(true);
    const [searchValue, setSearchValue] = useState("");
    const [dataSearch, setDataSearch] = useState([]);
    const [isError, setIsError] = useState(null);
    const [filterButton, setFilterButton] = useState(false)
    const [statusActivity, setStatusActivity] = useState("")
    const [newFilterDate, setNewFilterDate] = useState({
        start:stateHistory?.formatDate?.start,
        end:stateHistory?.formatDate?.end
    });
    const [pagination, setPagination] = useState({
        page:1,
        meta:{}
    })
    const dataTables = [
      
        {
            thead: "Name",
            tbody: "customer"
        },
        {
            thead: "Tanggal",
            tbody: "created_at"
        },
        {
            thead: "No Telepon",
            tbody: "phone"
        },
        {
            thead: "Email",
            tbody: "email"
        },
        {
            thead: "Status",
            tbody: "latest_activity",
            chdTbody: "latest_status"
        },
        {
            thead: "Nama Sales",
            tbody: "sales"
        },
        {
            thead: "Channel",
            tbody: "channel"
        }
    ]
  
    const handleClickEventTable = (data,event) => {
        history.push({
            pathname:`/dashboard/customers/customer_detail/${data.id}/${stateHistory.data.id}`,
            state:{idCustomer: data.id}
        })
    }
    useEffect(() => {
        console.log("check apakah mengalami loopin ginfinit")
        const config = {
            headers: {
              "Content-Type": "application/json",
              Authorization: `Bearer ${localStorage.token}`,
            },
        };
        const getDataNewLeads = () => {
            if(stateHistory === undefined || stateHistory === null || stateHistory === ""){
                return history.push('/dashboard')
            }
            Axios.get(`${mainUrl}/new-reports/leads?id=${stateHistory?.data?.id}&user_type=${stateHistory?.typeUser}&start_date=${newFilterDate.start}&end_date=${newFilterDate.end}&status=${statusActivity.toUpperCase()}&is_active=${stateHistory?.statusActive}&page=${pagination.page}`, config)
            .then(res => {
                if(res.status === 200){
                    setIsLoading(false);
                    setFilterButton(false);
                    setPagination((prev) => ({
                        ...prev,
                        meta:res.data
                    }))
                    return setIsData(res.data.data);
                }
            })
            .catch(error =>setIsError(error.response))
        }

        getDataNewLeads()
    }, [statusActivity, filterButton, pagination.page])
    useEffect(() => {
        const isSearchData = () => {
            let newRes = isData.filter((mData,i) => {
                if(mData.customer.toUpperCase().indexOf(searchValue.toUpperCase()) >= 0){
                    return mData
                }
            })
            setDataSearch(newRes)
        }
        !isLoading && isSearchData()
    }, [searchValue, isData, isLoading]);
    return(
        <>
            <div className='container'>
                <MyFilters 
                    setNewFilterDate={setNewFilterDate}
                    setStatusActivity={setStatusActivity}
                    setSearchValue={setSearchValue}
                    searchValue={searchValue}
                    setIsLoading={setIsLoading}
                    setFilterButton={setFilterButton}
                />
                <div style={{display:"flex", gap: "20px"}}>
                   {pagination?.meta?.prev_page_url !== null && <div >
                        <Button onClick={() => setPagination((prev) => ({
                            ...prev,
                            page: prev.page === 1 ? prev.page : prev.page - 1
                        }))}icon="" title="Prev" style={{width:"11rem"}} btnStyle="primary-btn" />
                    </div>}
                    {pagination?.meta?.next_page_url !== null && <div>
                        <Button onClick={() => setPagination((prev) => ({
                            ...prev,
                            page: prev.page + 1
                        }))}icon="" title="Next" style={{width:"11rem"}} btnStyle="primary-btn" />
                    </div>}
                    
                </div>
                {!isLoading && dataSearch.length !== 0 ? (<table className="data " style={{ margin: "10px 0", overflowX: "scroll", width:"100%" }}>
                    <thead>
                        <tr>
                            <th>No</th>
                        {
                            dataTables.map((data, indx) => {
                                return (
                                    <th key={indx}>{data.thead}</th>
                                )
                            })
                        }
                        </tr>
                    </thead>
                    <tbody>
                        {dataSearch.map((data, i) => {
                        
                        return (
                            <tr key={i} onClick={(e) => handleClickEventTable(data,e)}>
                                <td>{pagination?.meta?.from + i}</td>
                                {
                                    dataTables.map((dbody, indx) => {
                                        let hasil;
                                        
                                        if(data[dbody.tbody] === null){
                                            hasil = "No Activity"
                                        }else if(typeof data[dbody.tbody] === "object"){
                                            hasil = data[dbody.tbody][dbody?.chdTbody]
                                        }else if(dbody?.tbody === "created_at"){
                                            const getDate = new Date(data[dbody.tbody]);
                                            hasil = moment(getDate).format("YYYY-MM-DD");
                                        }else {
                                            hasil = data[dbody.tbody]
                                        }
                                        return (
                                            <td key={indx}>
                                                {hasil}
                                            </td>
                                        )
                                    })
                                }
                            </tr>
                        );
                        })}
                    </tbody>
                </table>): dataSearch.length === 0 && !isLoading ?  (<h3 style={{marginTop: "50px"}}>Hasil Tidak Ditemukan</h3>) :<LoadedComponent />}
                {!isLoading && <Button onClick={(e) => history.goBack()}icon="" title="Back" style={{width:"11rem!important", marginTop:"30px"}} btnStyle={"primary-btn"} />}
            </div>
        </>
    )
}
// theads, tbodies, clickTbody = false, dataTbody, showNo = false
export default NewLeadsSeeDetails