import React, {useEffect, useState, useMemo} from 'react';
import { useHistory, useParams } from 'react-router-dom';
import { mainUrl } from '../../../../api/api';
import { connect } from 'react-redux';
import Axios from 'axios';
import moment from 'moment';
import Button from '../../../../components/Button/Button';
import LoadedComponent from '../../../../components/Loaded/LoadedComponent';
import Activity from '../../../../components/ActivityDetail/Activity';
import { formatCurrency } from '../../../../api/format';
import InvoiceDetailHead from './InvoiceDetailHead';
import XLSX from "xlsx-js-style";
const InvoiceDetails = ({auth:user}) => {
    // const isUser = user.data
    const invoiceType = useMemo(() => ["deals", "cancelled", "down-payment", "partial"],[]);
    const params = useParams()
    const history = useHistory();
    const [isData, setIsData] = useState(null);
    const [isFiler, setIsFilter] = useState({
        nameofUserType:"",
        active: false
    })
    const [loadmoreOnTouch, setLoadmoreOnTouch] = useState({
        onTouch: true,
        page:1
    })
    const [onTouch, setOnTouch] = useState(true);
    const [dataUser, setDataUser] = useState({
        currentUser: null,
        currentPage: 1,
        hasNextPage: null
    });
    const [isTotal, setIsTotal] = useState(0)
    const [searchState, setSearchState] = useState({
        startDate: "",
        endDate: "",
        searchType:"customer",
        searchValue: "",
        userType: "bum",
        id_user: null,
        name_user:""
    })
    // Activiy Detail
    const [activityDetail, setActivityDetail] = useState(false);
    const [customerActivity, setCustomerActivity] = useState([]);
    const [orderId, setOrderId] = useState(null);

    // const buttonType = ["Quotation", "Settlement", "Deals", "Partial", "Down Payment"];

    const loopDataExp = (dataDetails) => {
    

        let objExp = {};
        const arrExp = [];
        dataDetails.forEach((isData, indx) => {
            const isDate = new Date(isData.created_at)
            const formatDate = moment(isDate).format("YYYY-MM-DD");
          objExp["Date"] = formatDate
          objExp["Invoice Number"] = isData?.invoice_number;
          objExp["Customer"] = isData?.customer;
          objExp["Sales Name"] = isData?.sales
          objExp["Channel Name"] = isData?.channel
          objExp[params?.invoice_type?.charAt(0)?.toUpperCase() + params?.invoice_type?.slice(1)] = formatCurrency(isData.total_price, true).replace(/([A-Za-z])\w+/g, '')
          arrExp.push(objExp);
          objExp = {};
        });
        return arrExp
    }
    // const textButtonInvoice = (stateHistory, invoiceType) => {
    //     let isInvType = invoiceType.find((type) => type.toUpperCase() === "QUOTATION").toLowerCase()
    //     if(stateHistory !== undefined && stateHistory !== null && stateHistory !== ""){
    //         if(invType === ""){
    //             const invoiceTypUpperCase = stateHistory?.invoiceType.toUpperCase();
    //             const resFindType = invoiceType.find((type) => type.toUpperCase() === invoiceTypUpperCase)
    //             isInvType = resFindType.toLowerCase()
    //         }else {
    //             isInvType = invType
    //         }
    //     } else {
    //         if(invType !== ""){
    //             isInvType = invType
    //         }
    //     }
    //     return isInvType
    // }
    const stylingXlsx = ({color, worksheet, cellRef}) => {
        worksheet[cellRef].s = {
          ...worksheet[cellRef].s,
          font: {
            sz: 14
          },
          fill:{
            type: 'pattern',
            pattern: 'solid',
            fgColor: { rgb: color }
          },
          border: {
            top: {style: "thin", color: {auto: 1}},
            right: {style: "thin", color: {auto: 1}},
            bottom: {style: "thin", color: {auto: 1}},
            left: {style: "thin", color: {auto: 1}}
          }
        }
      }
    const handleExportButton = async () => {
        // const resArrDataExp = loopDataExp(isData)
        const resArrDataExp = isData.map((data, i) => {
            const isDate = new Date(data.created_at)
            const formatDate = moment(isDate).format("YYYY-MM-DD");
            return {
                "No":i + 1,
                "Date": formatDate,
                "Customer": data?.customer,
                "Sales Name": data?.sales,
                "Channel Name": data?.channel,
                "Invoice Number": data?.invoice_number,
                [params?.invoice_type?.charAt(0)?.toUpperCase() + params?.invoice_type?.slice(1)]: formatCurrency(data.total_price, true).replace(/([A-Za-z])\w+/g, '')
            }
        });
        const wb = XLSX.utils.book_new();
        const worksheet = XLSX.utils.json_to_sheet(resArrDataExp);
        const range = XLSX.utils.decode_range(worksheet["!ref"] ?? "");
        const rowCount = range.e.r;
        const columnCount = range.e.c;
        var worksheetcols = [
          {wch:10},
          {wch:30},
          {wch:30},
          {wch:30},
          {wch:30},
          {wch:30},
          {wch:30},
        ];
      
        worksheet['!cols'] = worksheetcols;
        for (let row = 0; row <= rowCount; row++) {
            for (let col = 0; col <= columnCount; col++) {
              const cellRef = XLSX.utils.encode_cell({ r: row, c: col });
              // Add center alignment to every cell
              worksheet[cellRef].s = {
                alignment: { horizontal: "center" },
              };
              if(row === 0){
                worksheet[cellRef].s = {
                  ...worksheet[cellRef].s,
                  font: {
                    bold: true,
                    sz: 16,
                    color: {rgb: "00000"}
                  },
                  
                }
              }
              if(row !== 0){
                if(col === 0 || col === 1){
                  stylingXlsx({
                    worksheet,
                    cellRef,
                    color:"ffffffff"
                  })
                }
                if(col > 1 && col < 5){
                  stylingXlsx({
                    worksheet,
                    cellRef,
                    color:"ff4ca6c1"
                  })
                }
                if(col === 5 || col === 6){
                  stylingXlsx({
                    worksheet,
                    cellRef,
                    color:"ff94d244"
                  })
                }
              }
            }
          }

        XLSX.utils.book_append_sheet(wb, worksheet, `invoice-${params?.invoice_type}`);
        XLSX.writeFile(wb, `invoice-${params?.invoice_type}.xlsx`);
    };
   
    useEffect(() => {
        
        
        const config = {
            headers: {
              "Content-Type": "application/json",
              Authorization: `Bearer ${localStorage.token}`,
            },
        };
        const getUserList = async () => {
            const userType = ["store_leader", "bum", "hs"];
            const numberofSupervisor = userType.findIndex((user) =>  user === searchState?.userType);
            // const numberofSupervisor = searchState?.searchType === "hs" ? 3 : searchState?.searchType === "bum" ? 2 : 1
            Axios.get(`${mainUrl}/users?page=${loadmoreOnTouch.page}&filter[company_id]=${localStorage.getItem("company_id") !== undefined ? parseInt(localStorage.getItem("company_id")):""}&filter[supervisor_type_id]=${numberofSupervisor >= 0 ? numberofSupervisor + 1 : ""}&filter[type]=${searchState.searchType === "sales" ? searchState?.searchType?.toUpperCase() : "SUPERVISOR"}`, config)
            .then((user) => {
                const dataUsers = user?.data?.data
                setLoadmoreOnTouch((prev) => {
                    return {
                        ...prev,
                        onTouch: false
                    }
                })
                setDataUser((prev) => {
                    if(!prev.currentUser || loadmoreOnTouch.page === 1){
                        return {
                            ...prev,
                            currentUser: dataUsers,
                            hasNextPage: user?.data?.links?.next
                        }
                    }else {
                        if(loadmoreOnTouch.page > prev.currentPage){
                            return {
                                ...prev,
                                currentUser:[...prev.currentUser, ...dataUsers],
                                hasNextPage: user?.data?.links?.next
                            }
                        }
                        return {
                            ...prev,
                            currentUser: prev.currentUser,
                            hasNextPage: user?.data?.links?.next
                        }
                    }
                })
                
            })
            .catch((error) => console.log(error))
        }

        user && loadmoreOnTouch.onTouch && getUserList();

        const getDataInvoice = async () => {

            const splitInvoice = params?.invoice_type?.split("-")?.join("_") 
            Axios.get(`${mainUrl}/new-reports/invoice?id=${params?.id_user !== undefined ? params?.id_user : searchState.id_user ?? ""}&company_id=${localStorage.getItem("company_id") !== undefined ? parseInt(localStorage.getItem("company_id")):""}&user_type=${searchState.userType}&start_date=${searchState.startDate === "" && splitInvoice === "quotation" ? "2020-01-01" : searchState.startDate}&end_date=${searchState.endDate === "" && splitInvoice === "quotation" ? moment(new Date()).format("YYYY-MM-DD") : searchState.endDate}&invoice_type=${splitInvoice === "partial" || splitInvoice === "down_payment" ? "deals":splitInvoice}&payment_type=${invoiceType.some((d) => d === params.invoice_type) ? params.invoice_type?.split("-")?.join("_") : params.invoice_type === "settlement" ? "settlement" : ""}&search_type=${""}`, config)
            .then(data => {
                const result = data.data.data;
                let finalResultDataReportDetail = result
                if(searchState.searchValue !== ""){
                    finalResultDataReportDetail = result?.filter((datas,i) => datas[searchState.searchType]?.toUpperCase().indexOf(searchState.searchValue.toUpperCase()) >= 0 && datas)
                }
                
                setIsTotal(data.data.total)
                setOnTouch(false)
                setIsData(finalResultDataReportDetail);
            })
            .catch(error => console.log(error.response))
        } 
        
        user && onTouch && getDataInvoice()
    }, [searchState, params, onTouch, loadmoreOnTouch, dataUser, invoiceType, user]);
    
    const handleClickActivity = async (event, data) => {
        const config = {
            headers: {
              "Content-Type": "application/json",
              Authorization: `Bearer ${localStorage.token}`,
            },
        };
        Axios.get(`${mainUrl}/activities?filter[id]=${data.activity_id}`, config)
            .then(data => {
                setCustomerActivity(data.data.data);
                setActivityDetail(!activityDetail);
                setOrderId(data.data.data[0].order.id);
            })
            .catch(error => console.log(error.response))
    }  
    if(!isData){
        return <LoadedComponent />
    }
   
    return (
        <>
            <div className='container'>
                <div className='filter'>
                    <div className="col-auto d-flex" style={{gap:"20px", display:"flex", flexDirection:"column"}}>
                        <div style={{display:"flex"}}>
                            
                           
                            
                            <InvoiceDetailHead 
                                setOnTouch={setOnTouch} 
                                searchState={searchState} 
                                setSearchState={setSearchState} 
                                setLoadmoreOnTouch={setLoadmoreOnTouch} 
                                dataUsers={dataUser} 
                                setIsFilter={setIsFilter}
                            />
                        </div>
                        {/* <div className='btn-filter d-flex justify-content-around' style={{padding: "10px 0", flexWrap:"wrap"}}>
                            {
                                buttonType.map((data, i) => {
                                    return(
                                        <div onClick={handleClickEvent} style={{ position:"relative", cursor: "pointer", margin: "20px"}} key={i}>
                                            <span style={{color: "black", fontWeight:"bold"}}>{data}</span>
                                            <div style={{position: "absolute", bottom: "-10px", width: "100%", height: "4px", backgroundColor: "#17949d", display: params?.invoice_type?.split("-")?.join(" ")?.toUpperCase() === data?.toUpperCase() ? "block" : "none"}}></div>
                                        </div>
                                    )
                                })
                            }
                        </div> */}
                        <div style={{display:"flex", alignItems:"center", gap:"30px"}}>
                            <button style={{border:"0", outline:"0", padding:"10px 20px", borderRadius:"5px", background:"#17949d", color:"white"}} onClick={handleExportButton}>Export</button>
                            {!onTouch && isFiler.active && isFiler.nameofUserType !== "" ? (<h4>{isFiler.nameofUserType}: {formatCurrency(isTotal, true)}</h4>) : (<h4>Total: {formatCurrency(isTotal, true)}</h4>)}
                        </div>
                    </div>
                </div>
               
                {onTouch && (<LoadedComponent />)}
                {!onTouch && (<table className="data" style={{ margin: "10px 0", overflowX: "scroll", width:"100%" }}>
                        <thead>
                            <tr>
                                <th>Date</th>
                                <th>Invoice Number</th>
                                <th>Customer</th>
                                <th>Sales Name</th>
                                <th>Channel Name</th>
                                <th>{params?.invoice_type?.charAt(0).toUpperCase() + params?.invoice_type?.slice(1)}</th>
                                <th>Action</th>
                            </tr>
                        </thead>
                        <tbody>
                            {isData.map((data, i) => {
                                const isDate = new Date(data.created_at)
                                const formatDate = moment(isDate).format("YYYY-MM-DD");
                            return (
                                <tr key={i}>
                                    <td>{formatDate}</td>
                                    <td>{data.invoice_number}</td>
                                    <td>
                                        {data.customer}
                                    </td> 
                                    <td>{data.sales}</td>
                                    <td>{data.channel}</td>
                                    <td>
                                        {formatCurrency(data.total_price, true).replace(/([A-Za-z])\w+/g, '')}
                                    </td>
                                    <td>
                                        <div
                                        onClick={(e) => handleClickActivity(e,data)}
                                        className="activity-detail-btn"
                                        >
                                        <img
                                            src="/Asset/Action Icon/eye.png"
                                            style={{ marginRight: "5px" }}
                                            alt="eye"
                                        />
                                        See Detail
                                        </div>
                                    </td>
                                </tr>
                            );
                            })}
                        </tbody>
                </table>)}
                {
                    isData.length === 0 && !onTouch && (
                        <div>
                            <h4 style={{textAlign:"center"}}>Data Invoice Tidak Ada.</h4>
                        </div>
                    )
                }
               <Button onClick={() => history.push(`/dashboard`)} icon="" title="Back" style={{width:"11rem!important", marginTop:"30px"}} btnStyle={"primary-btn"} />
                {customerActivity.length !== 0 && <Activity
                    activityDetail={activityDetail}
                    setActivityDetail={setActivityDetail}
                    customerActivity={customerActivity[0]}
                    orderId={orderId}
                />}
            </div>
        </>
    )
}
const mapStateToProps = (state) => ({
    auth: state.auth,
    prosesData: state.prosesData
})
export default connect(mapStateToProps)(InvoiceDetails);
