import { mainUrl } from "../../../../api/api"
import axios from "axios"
import { config } from "../../../../api/api";
import { useQuery } from "react-query";
export const FetchUserList = async ({searchState}) => {
    return axios.get(`${mainUrl}/new-reports/details/users?start_date=${searchState.start ?? ""}&end_date=${searchState.end ?? ""}&user_type=${searchState.userType ?? "bum"}`, config)
    .then((res) => {
        return res.data.details
    })
    .catch(error => error)
}
export const useUserList = ({filterOnTouch}) => {
    return useQuery(["userList", {filterOnTouch}], () => {
        return axios.get(`${mainUrl}/new-reports/details/users?start_date=${filterOnTouch?.start}&end_date=${filterOnTouch?.end}&user_type=${filterOnTouch?.userType}&channel_id=${filterOnTouch?.channelId}`, config)
        .then((data) => {
            return data.data
        })
        .catch((error) => error)
    }, {refetchOnWindowFocus: (query) => query.state.status !== "error", staleTime: Infinity})
}

