import React, { useState, useEffect } from 'react';
import { mainUrl } from '../../../../api/api';
import { useHistory } from 'react-router-dom';
import LoadedComponent from '../../../../components/Loaded/LoadedComponent';
import Button from '../../../../components/Button/Button';
import { connect } from 'react-redux';
import Axios from 'axios';
import { formatCurrency } from '../../../../api/format';
const PipelinesSeeDetails = ({prosesData: {idCompany, dataFilterDate, idChannels}}) => {
    
    const config = {
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${localStorage.token}`,
        },
    };
    const history = useHistory();
    const stateHistory = history?.location?.state
    const [isData, setIsData] = useState([]);
    const [isLoading, setIsLoading] = useState(true);
    const [newFilterDate,setNewFilterDate] = useState({
        start:stateHistory?.formatDate?.start,
        end:stateHistory?.formatDate?.end
    });
    const [filterChannels, setFilterChannels] = useState(idChannels === undefined || idChannels === null ? "" : idChannels);
    const [filterButton, setFilterButton] = useState(false)
    useEffect(() => {
        const getDataPipelines = () => {
            Axios.get(`${mainUrl}/new-reports/brand-details?id=${stateHistory.data.id}&user_type=${stateHistory.typeUser}&end_date=${newFilterDate.end}&start_date=${newFilterDate.start}${filterChannels === "" ? "" : "&channel_id=" + filterChannels}`, config)
            .then(res => {
                if(res.status === 200){
                    setIsLoading(false)
                    setIsData(res.data.brand_details);
                    
                }
            })
            .catch(error => console.log(error.response, "check error pipelines"))
        }
        getDataPipelines()
    }, [stateHistory, filterButton]);
    const handleChangeDate = (e) => {
        setNewFilterDate(prev => {
            return{
                ...prev,
                [e.target.name]: e.target.value
            }
        })
    }
    const handleClickEventTable = () => {

    }
    return(
        <>
            <div className='container'>
                <div style={{display: "flex", alignItems: "center", width:"50%"}}>
                    <input
                        type="date"
                        id="start"
                        name="start"
                        className="form-control"
                        placeholder="Start Month"
                        value={dataFilterDate.start === undefined || dataFilterDate.start === null ? "" : dataFilterDate.start}
                        onChange={handleChangeDate}
                        style={{width: "20rem"}}
                        disabled
                    />
                    <div className="input-group-addon"style={{margin: "0 10px"}}>to</div>
                    <input
                        type="date"
                        id="end"
                        name="end"
                        className="form-control"
                        placeholder="End Month"
                        value={dataFilterDate.end === undefined || dataFilterDate.end === null ? "" : dataFilterDate.end}
                        onChange={handleChangeDate}
                        style={{margin:"0 20px 0 0", width: "20rem"}}
                        disabled
                    />
                    <Button onClick={(e) => {
                        setFilterButton(true);
                        setIsLoading(true);
                    }}icon="" title="Filter" style={{width:"15rem!important", marginTop:"30px"}} btnStyle={"primary-btn"} />
                </div>
                <h3 style={{margin:"20px 0"}}>{stateHistory.data.name}</h3>
                {isData.length !== 0 && !isLoading ? (<table className="data " style={{ margin: "10px 0", overflowX: "scroll", width:"100%" }}>
                    <thead>
                        <tr>
                            <th>No</th>
                            <th>Product Brand</th>
                            <th>Order Value</th>
                            <th>Pipelines</th>
                            <th>Quotation</th>
                            <th>Brand Category</th>
                        </tr>
                    </thead>
                    <tbody>
                        {
                            isData.length !== 0 && isData.map((dataList, inde) => {
                                return (
                                    <tr key={inde}  onClick={(e) => handleClickEventTable(dataList,e)}>
                                        <td>{inde + 1}</td>
                                        <td>{dataList.product_brand}</td>
                                        <td>{formatCurrency(dataList.order_value, true).replace(/([A-Za-z])\w+/g, '')}</td>
                                        <td>{formatCurrency(dataList.estimated_value, true).replace(/([A-Za-z])\w+/g, '')}</td>
                                        <td>{formatCurrency(dataList.quotation, true).replace(/([A-Za-z])\w+/g, '')}</td>
                                        <td>{dataList.brand_category}</td>
                                    </tr>
                                )
                            })
                        }
                    </tbody>
                </table>) : isData.length === 0 && !isLoading ?  (<h3 style={{marginTop: "50px"}}>Hasil Tidak Ditemukan</h3>) : <LoadedComponent />}
                {!isLoading && <Button onClick={(e) => history.goBack()}icon="" title="Back" style={{width:"11rem!important", marginTop:"30px"}} btnStyle={"primary-btn"} />}
            </div>
        </>
    )
}
const mapStateToProps = (state) => ({
    auth: state.auth,
    prosesData: state.prosesData
  });
export default connect(mapStateToProps)(PipelinesSeeDetails)