import axios from "axios";
import moment from "moment";
import React, { useEffect, useState } from "react";
import { useDispatch } from "react-redux";
import { useParams } from "react-router-dom";
import { mainUrl } from "../../api/api";
import { isValidate } from "../../lib/Validate";
import { loadChannels } from "../../redux/action/target";
import Activity from "../ActivityDetail/Activity";
import FilterLeadsReport from "../FilterForm/FilterLeadsReport";
import Header from "../Header/Header";
import LoadedComponent from "../Loaded/LoadedComponent";
import Button from "../Button/Button";
const ReportLeadStatus = () => {
  const params = useParams();
  const { user_type, user_id, detail_type, start, end } = params;
  const [activityDetail, setActivityDetail] = useState(false);
  const [customerActivity, setCustomerActivity] = useState(null);
  const [orderId, setOrderId] = useState(null);
  const [reportDataStatus, setReportDataStatus] = useState(null);
  const [isLoading, setIsLoading] = useState(false);
  const dispatch = useDispatch();
  // filter
  const [mount, setMount] = useState(1);
  const [filterCompany, setFilterCompany] = useState();
  const [filterStartDate, setFilterStartDate] = useState(
    start !== "now" ? start : ""
  );
  const [filterEndDate, setFilterEndDate] = useState(end !== "now" ? end : "");
  useEffect(() => {
    const startDate = localStorage.getItem("date_leads_start")
        
    const endDate = localStorage.getItem("date_leads_end");
    if(startDate === undefined || startDate === null){
      localStorage.setItem("date_leads_start", params.start === "now" ? "" : params.start)
      if(endDate === undefined || endDate === null){
        localStorage.setItem("date_leads_end", params.end === "now" ? "" : params.end);
      }
     
    }
  },[params])
  useEffect(() => {
    dispatch(loadChannels(filterCompany));
    const config = {
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${localStorage.token}`,
      },
    };
   
    const getReportDeal = async () => {
      const isTypeUser = await localStorage.getItem("user_type_leads_filter");
      const isChannels = await localStorage.getItem("channels_leads_filter");
      const dateStart = params.start !== "now" ? params.start : localStorage.getItem("date_leads_start") === undefined || localStorage.getItem("date_leads_start")  === null ? "" : localStorage.getItem("date_leads_start") ;
      const dateEnd = params.end !== "now" ? params.end : localStorage.getItem("date_leads_end") === undefined || localStorage.getItem("date_leads_end") === null ? "" : localStorage.getItem("date_leads_end") ;
      const checkChannels = isChannels === undefined || isChannels === null ? true : false
      
      setIsLoading(true);
      try {
        const res = await axios.get(
          `${mainUrl}/dashboard/report-leads/status-new?start_date=${
            dateStart === "now" ? "" : dateStart
          }&end_date=${
            dateEnd === "now" ? "" : dateEnd
          }&company_id=${filterCompany ? filterCompany : ""}&${
            isTypeUser === "sales"
          ?"sales_id=" + parseInt(user_id ?? "")
          : isTypeUser === "store"
            ? "channel_id=" + parseInt(user_id ?? "")
            : "supervisor_id=" + parseInt(user_id ?? "")
          }&status=${detail_type.toUpperCase()}&perPage=100&page=${mount}`,
          config
        );
        setReportDataStatus(res.data);
        setIsLoading(false);
      } catch (error) {
        console.error(error);
        setIsLoading(false);
      }
    };

    getReportDeal();
  }, [
    dispatch,
    user_type,
    user_id,
    detail_type,
    filterCompany,
    filterStartDate,
    filterEndDate,
    mount,
  ]);

  const exportReportStatus = async () => {
    const isTypeUser = await localStorage.getItem("user_type_leads_filter");
      const isChannels = await localStorage.getItem("channels_leads_filter");
    axios
      .get(
        `${mainUrl}/dashboard/report-leads/status?start_date=${
          filterStartDate ? moment(filterStartDate).format("YYYY-MM-DD") : ""
        }&end_date=${
          filterEndDate ? moment(filterEndDate).format("YYYY-MM-DD") : ""
        }&company_id=${filterCompany ? filterCompany : ""}&${
          isTypeUser === "sales"
          ?"sales_id=" + parseInt(params.user_id ?? "")
          : isTypeUser === "store"
            ? "channel_id=" + parseInt(params.user_id ?? "")
            : "supervisor_id=" + parseInt(params.user_id ?? "")
        }&status=${detail_type.toUpperCase()}&perPage=100&is_export=1`,
        {
          method: "GET",
          responseType: "blob", // important
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${localStorage.token}`,
          },
        }
      )
      .then((response) => {
        const url = window.URL.createObjectURL(new Blob([response.data]));
        const link = document.createElement("a");
        link.href = url;
        link.setAttribute(
          "download",
          `Report ${detail_type} ${user_type}.xlsx`
        );
        document.body.appendChild(link);
        link.click();
      })
      .catch((err) => {
        console.log();
      });
  };
  
  const handleClickDetail = async (activity) => {
    console.log(activity,'act')
    try {
      const res = await axios.get(
        `${mainUrl}/activities?filter[id]=${activity?.latest_activity?.id}`,
        {
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${localStorage.token}`,
          },
        }
      );
      setCustomerActivity(res.data.data[0]);
    } catch (error) {
      console.error(error);
    }
    setActivityDetail(!activityDetail);
    // setCustomerActivity(activity);
    setOrderId(activity.order ? activity.order.id : null);
  };
 
  return (
    <div>
      <Header
        icon=""
        title={`Report Leads - ${detail_type.toUpperCase()}`}
        back={true}
        user={false}
      />

      <FilterLeadsReport
        company={false}
        channel={false}
        supervisor={false}
        download={exportReportStatus}
        setFilterStartDate={setFilterStartDate}
        setFilterEndDate={setFilterEndDate}
      />
      {isLoading ? (
        <LoadedComponent />
      ) : (
        <div style={{ overflow: "scroll" }}>
          <table className="" style={{ margin: "10px 0" }}>
            <thead>
              <tr>
                <th>No.</th>
                <th>Date</th>
                <th>Lead</th>
                {detail_type === "hot" && <th>Invoice Number</th>}
                <th>Follow Up</th>
                <th>Store Location</th>
                {detail_type === "hot" && <th>Payment</th>}
                {detail_type === "hot" && <th>Quotation</th>}
                <th>Sales</th>
                <th>Status</th>
                <th>Action</th>
              </tr>
            </thead>
            <tbody>
              {reportDataStatus &&
                reportDataStatus?.data?.map((activity, idx) => {
                  return (
                    <tr key={activity.id}>
                      <td>{reportDataStatus?.meta?.from + idx}</td>
                      <td>
                        {!isValidate(activity?.created_at)
                          ? moment(activity?.created_at).format(
                              "MM/DD/YYYY"
                            )
                          : ""}
                      </td>
                      <td>
                        {!isValidate(activity.label)
                          ? `${activity.label}`
                          : ""}
                      </td>
                      {detail_type === "hot" && (
                        <td>
                          {!isValidate(activity.order)
                            ? activity.order.invoice_number
                            : ""}
                        </td>
                      )}

                      <td>
                        {!isValidate(activity?.latest_activity?.follow_up_method)
                          ? activity.latest_activity?.follow_up_method + ""
                          : ""}
                      </td>
                      <td>
                        {!isValidate(activity.channel.name)
                          ? activity.channel.name
                          : ""}
                      </td>
                      {detail_type === "hot" && (
                        <td>
                          {!isValidate(activity.order)
                            ? activity.order.payment_status
                            : ""}
                        </td>
                      )}
                      {detail_type === "hot" && (
                        <td>
                          {!isValidate(activity.order)
                            ? activity.order.status
                            : ""}
                        </td>
                      )}

                      <td>
                        {!isValidate(activity.user.name)
                          ? activity.user.name
                          : ""}
                      </td>
                      <td>
                        {!isValidate(activity.status) ? activity.status : ""}
                      </td>
                      <td>
                        <div
                          onClick={() => handleClickDetail(activity)}
                          className="activity-detail-btn"
                        >
                          <img
                            src="/Asset/Action Icon/eye.png"
                            style={{ marginRight: "5px" }}
                            alt="eye"
                          />
                          See Detail
                        </div>
                      </td>
                    </tr>
                  );
                })}
            </tbody>
          </table>
          <div style={{display:"flex", gap:"20px", marginTop:"50px", alignItems:"center"}}>
          <div style={{display: reportDataStatus?.links?.prev === null ? "none" : "block"}}>
          <Button
                onClick={(e) => setMount((prev) => prev-1)}
                icon=""
                title={"Prev"}
                style={{ width: "11rem!important"}}
                btnStyle={"primary-btn"}
              />
              </div>
              
              <div style={{display: reportDataStatus?.links?.next === null ? "none" : "block"}}>
               <Button
                onClick={(e) => {setMount((prev) => prev+1)}}
                icon=""
                title={"Next"}
                style={{ width: "11rem!important", display: reportDataStatus?.links?.next === null ? "none" : "block"}}
                btnStyle={"primary-btn"}
              />
              </div>
        </div>
        </div>
      )}
      {customerActivity ? (
        <Activity
          activityDetail={activityDetail}
          setActivityDetail={setActivityDetail}
          customerActivity={customerActivity}
          orderId={orderId}
        />
      ) : (
        ""
      )}
    </div>
  );
};

export default ReportLeadStatus;
