import { useQuery } from "react-query";
import { mainUrl, config } from "../../../api/api";
import axios from "axios";

const useReportLeadsStatusHotList = ({searchState}) => 
{
    return useQuery(["reportLeadsStatusHotList", searchState], () => {
        return axios.get(
            `${mainUrl}/dashboard/report-leads/hot-new?start_date=${
                searchState.start
            }&end_date=${
                searchState.end
            }&company_id=${searchState.companyId}&${
                searchState.userType === "bum" || searchState.userType === "hs" || searchState.userType === "store_leader"
                ? "supervisor_id=" + searchState.userId
                : searchState.userType === "store"
                    ? "channel_id=" + searchState.userId
                    : "sales_id=" + searchState.userId
            }&status=${searchState.status?.toUpperCase()}&perPage=100&page=${searchState.count}`,
            config
          ).then((result) => result?.data)
            .catch((error) => error);
    }, {refetchOnWindowFocus: (query) => query.state.status !== "error", staleTime: Infinity})
}

export default useReportLeadsStatusHotList


