import axios from "axios";
import moment from "moment";
import React, { useEffect, useState } from "react";
import { connect, useDispatch } from "react-redux";
import { mainUrl } from "../../../api/api";
import LoadedComponent from "../../../components/Loaded/LoadedComponent";
import { loadSalesRanking } from "../../../redux/action/target";
import { pickColor } from "../../../api/pickColor";
import Loaded from "../../../components/Loaded/Loaded";
import { Link } from "react-router-dom";
import { formatCurrency } from "../../../api/format";


const TopPerformance = (
  {
    auth: { user, loading },
    target: { salesRanking },
    prosesData: { dataFilterDate, idCompany },
  },
  props
) => {
  let today = new Date();
  const startDate = dataFilterDate.start === undefined || dataFilterDate.start === null || dataFilterDate.start === "" ? moment(today).startOf("month").format("YYYY-MM-DD") : dataFilterDate.start;
  const endDate = dataFilterDate.end === undefined || dataFilterDate.end === null || dataFilterDate.end === "" ? moment(today).endOf("month").format("YYYY-MM-DD") : dataFilterDate.end;
  const [topSales, setTopSales] = useState(null);
  const [topBum, setTopBum] = useState(null);
  const [topChannel, setTopChannel] = useState(null);
  useEffect(() => {
    const config = {
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${localStorage.token}`,
      },
    };
    const getTopPerformance = async () => {
    if(user.data.as === 'BUM' || user.data.as === 'Director' || user.data.as === 'HS'){
      try {
        const res = await axios.get(
          `${mainUrl}/dashboard/top-sales/value?company_id=${idCompany}&start_at=${startDate}&end_at=${endDate}&user_type=bum&limit=5`,
          config
        );
        setTopBum(res.data.sort((a,b) => {return b.percentage - a.percentage}));
      } catch (error) {
        console.error(error);
      }
      try {
        const res = await axios.get(
          `${mainUrl}/dashboard/top-sales/value?company_id=${idCompany}&start_at=${startDate}&end_at=${endDate}&user_type=store&limit=5`,
          config
        );
        setTopChannel(res.data.sort((a,b) => {return b.percentage - a.percentage}));
      } catch (error) {
        console.error(error);
      }
      try {
        const res = await axios.get(
          `${mainUrl}/dashboard/top-sales/value?company_id=${idCompany}&start_at=${startDate}&end_at=${endDate}&user_type=sales&limit=5`,
          config
        );
        setTopSales(res.data.sort((a,b) => {return b.percentage - a.percentage}));
      } catch (error) {
        console.error(error);
      }
    }
    else{
      try {
        const res = await axios.get(
          `${mainUrl}/dashboard/top-sales/value?company_id=${idCompany}&start_at=${startDate}&end_at=${endDate}&user_type=sales&limit=5`,
          config
        );
        setTopSales(res.data.sort((a,b) => {return b.percentage - a.percentage}));
      } catch (error) {
        console.error(error);
      }
    };
    };
    getTopPerformance();
  }, [startDate, endDate, idCompany]);
 
  return (
    <div className="ranking">
      <div className="top-ranking mt-4 d-flex justify-content-between">
        <div className="d-flex align-items-center">
          <img
            src="/Asset/Icon/Top Sales.png"
            alt="report"
            style={{ width: "22px", height: "22px", marginRight: "13px" }}
          />
          <h3
            style={{
              fontStyle: "normal",
              fontWeight: "700",
              fontSize: "16px",
              lineHeight: "24px",
              margin: "0",
              color: "#313132",
            }}
          >
            Top Performance
          </h3>
        </div>
      </div>

      {user.data.type === "DIRECTOR" || user?.data?.as === "HS" ? (
        <div className="mt-4 bum-table">
          <h2>BUM</h2>
          {topBum ? (
            <table className="data " style={{ margin: "10px 0" }}>
              <thead>
                <tr>
                  <th>No</th>
                  <th>BUM Name</th>
                  <th>Meet Goal</th>
                  <th>Revenue</th>
                  <th>Target</th>
                  {/* <th>Channel</th> */}
                  <th>Action</th>
                </tr>
              </thead>
              <tbody>
                {topBum.map((data, i) => {
                  const percentage = Math.round(
                    (data.value / data.target) * 100
                  );
                  return (
                    <tr key={i}>
                      <td>{i + 1}.</td>
                      <td>{data.name ? data.name : ""}</td>
                      <td
                        style={{
                          color: pickColor(percentage),
                          fontWeight: "bold",
                        }}
                      >
                        {data.percentage}%
                      </td>
                      <td>{formatCurrency(Math.round(data.value))}</td>
                      <td>{formatCurrency(Math.round(data.target))}</td>
                      {/* <td>
                        {data.channel ? data.channel.name : ""}
                      </td> */}
                      <td>
                        <Link
                          to={`/dashboard/top-performance/${
                            user ? user.data.company.id : "1"
                          }/${moment(startDate).format("YYYY-MM")}`}
                        >
                          <img
                            src="/Asset/Action Icon/eye.png"
                            style={{ marginRight: "5px" }}
                            alt="eye"
                          />
                          See Detail
                        </Link>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          ) : (
            <Loaded />
          )}
        </div>
      ) : (
        ""
      )}

      {user.data.as === "BUM" ||
      user.data.as === "Director" ||
      user?.data?.as === "HS" ? (
        <div className="mt-4 channel-table">
          <h2>Channel</h2>
          {topChannel ? (
            <table className="data" style={{ margin: "10px 0" }}>
              <thead>
                <tr>
                  <th>No</th>
                  <th>Channel Name</th>
                  <th>Meet Goal</th>
                  <th>Revenue</th>
                  <th>Target</th>
                  <th>Action</th>
                </tr>
              </thead>
              <tbody>
                {topChannel.map((data, i) => {
                  const percentage = Math.round(
                    (data.value / data.target) * 100
                  );
                  return (
                    <tr>
                      <td>{i + 1}.</td>
                      <td>{data.name ? data.name : ""}</td>
                      <td
                        style={{
                          color: pickColor(percentage),
                          fontWeight: "bold",
                        }}
                      >
                        {data.percentage}%
                      </td>
                      <td>{formatCurrency(Math.round(data.value))}</td>
                      <td>{formatCurrency(Math.round(data.target))}</td>
                      <td>
                        <Link
                          to={`/dashboard/top-channel/${
                            user ? user.data.company.id : "1"
                          }/${moment(startDate).format("YYYY-MM")}`}
                        >
                          <img
                            src="/Asset/Action Icon/eye.png"
                            style={{ marginRight: "5px" }}
                            alt="eye"
                          />
                          See Detail
                        </Link>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          ) : (
            <Loaded />
          )}
        </div>
      ) : (
        ""
      )}

      <div className="mt-4 sales-table">
        <h2>Sales</h2>
        {topSales ? (
          <table className="data " style={{ margin: "10px 0" }}>
            <thead>
              <tr>
                <th>No</th>
                <th>Sales Name</th>
                <th>Meet Goal</th>
                <th>Revenue</th>
                <th>Target</th>
                {/* <th>Channel</th> */}
                <th>Action</th>
              </tr>
            </thead>
            <tbody>
              {topSales.map((data, i) => {
                const percentage = Math.round((data.value / data.target) * 100);
                return (
                  <tr>
                    <td>{i + 1}.</td>
                    <td>{data.name}</td>
                    <td
                      style={{
                        color: pickColor(percentage),
                        fontWeight: "bold",
                      }}
                    >
                      {data.percentage}%
                    </td>
                    <td>{formatCurrency(Math.round(data.value))}</td>
                    <td>{formatCurrency(Math.round(data.target))}</td>
                    {/* <td>{data.channel ? data.channel.name : ""}</td> */}
                    <td>
                      <Link
                        to={`/dashboard/top-sales/sales/${
                          user ? user.data.company.id : "1"
                        }/${moment(startDate).format("YYYY-MM")}/0`}
                      >
                        <img
                          src="/Asset/Action Icon/eye.png"
                          style={{ marginRight: "5px" }}
                          alt="eye"
                        />
                        See Detail
                      </Link>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        ) : (
          // <LoadedComponent />
          null
        )}
      </div>
    </div>
  // ) : (
  //   <LoadedComponent />
  // );
  )
};

const mapStateToProps = (state) => ({
  auth: state.auth,
  target: state.target,
  prosesData: state.prosesData,
});

export default connect(mapStateToProps)(TopPerformance);
