import axios from "axios";
import React, { useEffect, useState } from "react";
import { connect } from "react-redux";
import { mainUrl } from "../../api/api";
import Button from "../Button/Button";
import "./FilterLeadsReport.scss";
import "react-date-range/dist/styles.css"; // main css file
import "react-date-range/dist/theme/default.css"; // theme css file
import { roleUserType } from "./RoleUserType";
const FilterLeadsReport = ({
  target: { channels },
  filterCompany,
  setFilterChannels,
  setFilterCompany,
  setFilterDate,
  setFilterSupervisor,
  download,
  setUserType,
  userType,
  setFilterStartDate,
  setFilterEndDate,
  company,
  channel,
  supervisor,
  setFilterBrand,
  brand,
  setIsEnabled,
  user
}) => {
  const [supervisors, setSupervisors] = useState(null);
  const [brands, setBrands] = useState(null);
  const [userTypeLeads, setUserTypeLeads] = useState(null);
  const isUser = user?.data?.as?.toLowerCase()?.split(" ")?.join("_");
  const isUserType = localStorage.getItem("user_type_leads_filter") 
  
  useEffect(() => {
    setUserTypeLeads(isUserType)
    
  }, [isUserType])
  useEffect(() => {
    const config = {
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${localStorage.token}`,
      },
    };
    const getSupervisors = async () => {
      try {
        const res = await axios.get(
          `${mainUrl}/users?filter[type]=SUPERVISOR&filter[descendant_of]=10&perPage=50`,
          config
        );
        setSupervisors(res.data);
      } catch (error) {
        console.error(error);
      }
    };

    const getBrands = async () => {
      try {
        const res = await axios.get(`${mainUrl}/brands`, config);
        setBrands(res.data.data);
      } catch (error) {
        console.error(error);
      }
    };

    getBrands();

    getSupervisors();
  }, []);

  return (
    <>
    <div
      className="filter-leads-report d-flex "
      id="filter-leads-report"
      style={{gap:"20px", marginBottom:"20px"}}
    >
      <div className="report-filter-form d-flex" style={{gap:"10px"}}>
        {company && (
          <select
            className="form-select"
            name="companys"
            value={localStorage.getItem("company_leads_filter")}
            onChange={(e) => {
              if(e.target.value === ""){
                localStorage.removeItem("company_leads_filter")
              }else{
                localStorage.setItem("company_leads_filter", e.target.value)
              }
              setFilterCompany(e.target.value)
            }}
          >
            <option value="">Select Company</option>
            <option value={1}>Melandas</option>
            <option value={2}>Dio Living</option>
          </select>
        )}
        {channel && (
          <select
            className="form-select"
            name="channels"
            value={localStorage.getItem("channels_leads_filter")}
            onChange={(e) => {
            
              if(e.target.value === ""){
                localStorage.removeItem("channels_leads_filter");
              }else {
                localStorage.setItem("channels_leads_filter", e.target.value);
              }
              setFilterChannels(parseInt(e.target.value))
            }}
          >
            <option value="">Select Channel</option>
            {channels &&
              channels?.data?.map((channel) => {
                return (
                  <option value={channel.id} key={channel.id}>
                    {channel.name}
                  </option>
                );
              })}
          </select>
        )}
        {(
          <select
            className="form-select"
            name="user"

            onChange={(e) => {
           
              localStorage.setItem("user_type_leads_filter", e.target.value ?? "")
              setUserType(e.target.value)}}
            value={userTypeLeads ?? userType}
          >
           
            {isUser && roleUserType[isUser]?.map((data) => {
              return (
                <option value={data?.key}>{data?.role}</option>
              )
            }) }
          </select>
        )}
        {/* {supervisor && (
          <select
            className="form-select"
            name="supervisors"
            onChange={(e) => setFilterSupervisor(parseInt(e.target.value))}
          >
            <option value="">Select Supervisor</option>
            {supervisors &&
              supervisors.data.map((supervisor) => {
                return (
                  <option value={supervisor.id} key={supervisor.id}>
                    {supervisor.name}
                  </option>
                );
              })}
          </select>
        )} */}
        {/* {brand && (
          <select
            className="form-select"
            name="supervisors"
            onChange={(e) => setFilterBrand(parseInt(e.target.value))}
          >
            <option value="">Select Brands</option>
            {brands &&
              brands.map((brand) => {
                return (
                  <option value={brand.id} key={brand.id}>
                    {brand.name}
                  </option>
                );
              })}
          </select>
        )} */}
       
        <div className="d-flex align-items-center ms-1">
          <label>Start: </label>
          <input
            type="date"
            id="start"
            name="start"
            className="form-control"
            value={localStorage.getItem("date_leads_start")}
            onChange={(e) => {
           
              localStorage.setItem("date_leads_start", e.target.value)
              setFilterStartDate(e.target.value)
            }}
          />
        </div>
        <div className="d-flex align-items-center ms-1 me-3">
          <label>End: </label>
          <input
            type="date"
            id="end"
            name="end"
            className="form-control"
            value={localStorage.getItem("date_leads_end")}
            onChange={(e) => {
             
              localStorage.setItem("date_leads_end", e.target.value)
              setFilterEndDate(e.target.value)
            }}
          />
        </div>
      </div>
      {/* {download && (
        <div>
          <div onClick={() => download()} style={{ width: "fit-content" }}>
            <Button icon="" title="Export excel" btnStyle={"outline-btn"} />
          </div>
        </div>
      )} */}
      <Button onClick={() => {
       
        localStorage.removeItem("date_leads_start")
        localStorage.removeItem("date_leads_end")
        window.location.reload()
      }}
      icon=""
            title="Reset Filter"
            style={{ width: "11rem!important" }}
            btnStyle={"primary-btn"}
      ></Button>
    </div>
   
    </>
  );
};

const mapStateToProps = (state) => ({
  target: state.target,
});

export default connect(mapStateToProps)(FilterLeadsReport);
