import React, { useEffect, useState } from "react";
import { useHistory } from "react-router-dom";
import { mainUrl } from "../../api/api";
import axios from "axios";
import Button from "../Button/Button";
import moment from "moment";
// import fs from 'fs-extra';
const FppRequest = () => {
    const history = useHistory();
    const stateHistory = history?.location?.state;
    const isNewDate = new Date(stateHistory?.data?.follow_up_datetime);
    const [orderData, setOrderData] = useState(null);
    const [valuesRequest, setValuesRequest] = useState({
        expected_shipping_datetime: (stateHistory?.data?.follow_up_datetime === undefined || stateHistory?.data?.follow_up_datetime === null) ? "" : moment(isNewDate).format(`YYYY-MM-DD${"T"}HH:mm`),
        note: "",
        addres: ""
    });
    const [productSelect, setProductSelect] = useState([]);
    const [countProducts, setCountProducts] = useState({})
    useEffect(() => {
        if(!stateHistory){
            history.goBack(-1)
        }else{
            const config = {
                headers: {
                  "Content-Type": "application/json",
                  Authorization: `Bearer ${localStorage.token}`,
                },
              };
            
             
              const getOrderData = async () => {
                try {
                  const res = await axios.get(
                    `${mainUrl}/orders?filter[id]=${stateHistory.orderId}`,
                    config
                  );
                  const orderData = res.data.data[0]
                  setValuesRequest((prev) => ({
                    ...prev,
                    addres: orderData.shipping_address.address_line_1
                  }))
                  setOrderData(res.data.data[0]);
                
                } catch (error) {
                  console.log(error)
                }
              };
          
              getOrderData();
        }
    }, [stateHistory, history]);
    const generateNumberToText = (number = 0) => {
        if(number === undefined || number === null) return;
        const alfabet = ["a","b","c","d","e","f","g","h", "i", "j", "k"]
        const numberToString = number.toString();
        let result = ""
        for(let i = 0; i <= numberToString.length - 1; i++){
            const stringTonumber = parseInt(numberToString[i]);
            result += alfabet[stringTonumber]
        }
        
        return result
    }
   const handleProducts = (id) => {
    if(parseInt(id) === 0) return;

    const filterOrder = orderData.order_details.filter((order) => parseInt(id) === order.id)[0];
    setCountProducts((prev) => {
        const textGenerated = generateNumberToText(filterOrder.id);
        const checkHaveSameId = productSelect.some((order) => parseInt(order.id) === parseInt(id));
        if(!checkHaveSameId){
            return {
                ...prev,
                [textGenerated]:filterOrder.quantity
            } 
        }
        return prev
        
    })
    setProductSelect((prev) => {
        const checkHaveSameId = prev.some((order) => parseInt(order.id) === parseInt(id));
        if(!checkHaveSameId){
            return [...prev, filterOrder]
        }
        return prev
    })
   }

   const handleSubmit = (event) => {
    event.preventDefault();
    let paramsItems = null
    const config = {
        headers: {
              Accept: "application/json, text-plain, */*",
              Authorization: `Bearer ${localStorage.token}`,
        },
    };
    if(productSelect.length){
        paramsItems = productSelect.map((product,i) => {
            return `items[${i}][id]=${product?.product_unit?.id}&items[${i}][qty]=${countProducts[generateNumberToText(product.id)]}`
        })
    }

    axios.get(mainUrl + `/orders/${stateHistory.orderId}/fpp?address=${valuesRequest.addres}&expected_shipping_datetime=${valuesRequest.expected_shipping_datetime}&note=${valuesRequest.note}&${!paramsItems ? "" : paramsItems.join("&")}`,
        {
            method: "GET",
            responseType: "blob", //Force to receive data in a Blob Format
            headers: config.headers
        })
    .then( (response) => {
      //Create a Blob from the PDF Stream
      const file = new Blob([response.data], { type: "application/pdf" });
      //Build a URL from the file
      const fileURL = URL.createObjectURL(file);
      //Open the URL on new Window
      window.open(fileURL);
    })
    .catch((error) => console.log(error, "checking error"))


   }
    return (
        <>
            <div>
                <div style={{
                    display:"flex",
                    alignItems:"center",
                    gap:"20px",
                    cursor:"pointer",
                    width:"max-content"
                }} onClick={() => history.goBack(-1)}>
                    <img src="/Asset/Back.png" alt="back" style={{
                        width:"20px",
                        height:"20px"
                    }}/>
                    <h3 style={{margin:0, padding:0}}>
                        FPP Request
                    </h3>
                </div>
                <div>
                <form onSubmit={handleSubmit}> 
                    <div style={{
                        display:"flex",
                        gap:"20px",
                        flexDirection:"column"
                    }}>
                    <div className="form-group">
                        <label for="dateTime">Date time</label>
                        <input
                            type="datetime-local"
                            id="dateTime"
                            name="dateTime"
                            value={valuesRequest.expected_shipping_datetime}
                            className="form-control"
                            placeholder="Start Month"
                            onChange={(e) => setValuesRequest((prev) => ({
                                ...prev,
                                expected_shipping_datetime:e.target.value
                            }))}
                        />
                       
                    </div>
                    <div className="form-group">
                        <label for="inputText">Address</label>
                        <input type="text" className="form-control" value={valuesRequest.addres} id="inputText" aria-describedby="textHelp" placeholder="Enter addres" onChange={(e) => setValuesRequest((prev) => ({
                            addres:e.target.value
                        }))}/>
                       
                    </div>
                    <div className="form-group">
                        <label for="exampleInputPassword1">Note.</label>
                        <input type="text" className="form-control" id="exampleInputPassword1" placeholder="Enter note" onChange={(e) => setValuesRequest((prev) => ({
                            ...prev,
                            note:e.target.value
                        }))}/>
                    </div>
                    <div className="form-group">
                    <label for="exampleInputPassword1">Select products.</label>
                        <select className="form-control" onChange={(e) => handleProducts(e.target.value)}>
                            <option value={0}>Select product</option>
                            {
                                orderData && orderData?.order_details?.map((data) => (
                                    <option value={data.id} key={data.id}>{data.product_unit.name}</option>
                                ))
                            }
                    </select>
                    </div>
                    <div>
                        <h5>Products List</h5>
                        {
                        (!productSelect || productSelect.length === 0)
                            ? "No product selected"
                            : (
                                <div style={{
                                    gap:"20px",
                                    display:"flex",
                                    flexDirection:"column"
                                }}>
                                    {
                                        productSelect.map((product) => (
                                            <div key={product.id} style={{
                                                display:"flex",
                                                gap:"15px"
                                            }}>
                                                <img src={product?.images[0]?.url} alt="thumbnail product" style={{
                                                    width:"100px",
                                                    height:"100px"
                                                }}/>
                                                <div>   
                                                    <h4 style={{fontSize:"15px"}}>{product.product_unit.name}</h4>
                                                    <span >Quantity: {product.quantity}</span>
                                                    <div style={{
                                                        display:"flex",
                                                        gap:"20px",
                                                        marginTop:"20px"
                                                    }}>
                                                       <button type="button" onClick={(e) => {
                                                            const textGenerated = generateNumberToText(product.id);
                                                            setCountProducts((prev) => {
                                                                if(prev[textGenerated] === undefined || prev[textGenerated] === null){
                                                                    
                                                                    return {
                                                                        ...prev,
                                                                        [textGenerated]: product.quantity - 1
                                                                    }
                                                                }

                                                                return {
                                                                    ...prev,
                                                                    [textGenerated]: prev[textGenerated] === 0 ? 0 : prev[textGenerated] - 1
                                                                }
                                                            })
                                                        }} style={{
                                                            background:"#20b5c0",
                                                            border:0,
                                                            outline:"none",
                                                            borderRadius:"5px",
                                                            color:"white",
                                                            fontWeight:"bold"
                                                        }}>-</button>
                                                        <span style={{fontSize:"20px"}}>{
                                                            countProducts[generateNumberToText(product.id)]
                                                        }</span>
                                                        <button type="button" onClick={(e) => {
                                                            const textGenerated = generateNumberToText(product.id);
                                                            setCountProducts((prev) => {
                                                                return {
                                                                    ...prev,
                                                                    [textGenerated]: prev[textGenerated] >= product.quantity ? product.quantity : prev[textGenerated] + 1
                                                                }
                                                                // if(prev[textGenerated] === undefined || prev[textGenerated] === null){
                                                                    
                                                                //     return {
                                                                //         ...prev,
                                                                //         [textGenerated]: product.quantity === 1 ? 1 : product.quantity + 1
                                                                //     }
                                                                // }

                                                                // return {
                                                                //     ...prev,
                                                                //     [textGenerated]: prev[textGenerated] + 1
                                                                // }
                                                            })
                                                        }} style={{
                                                            background:"#20b5c0",
                                                            border:0,
                                                            outline:"none",
                                                            borderRadius:"5px",
                                                            color:"white",
                                                            fontWeight:"bold"
                                                        }}>+</button>
                                                    </div>
                                                </div>
                                            </div>
                                        ))
                                    }
                                </div>
                            )
                        }
                    </div>
                    <Button
                        title={"Request Fpp"}
                        btnStyle={"primary-btn"}
                        btnWidth={"max-content"}
                        disabled={false}
                    />
                    </div>
                </form>
                </div>
            </div>
        </>
    )
}

export default FppRequest;
