import { REPORT_LEADS_BRAND_ID, REPORT_LEADS_CURRENT_CHANNEL, REPORT_LEADS_START_END_DATE, REPORT_LEADS_COMPANY_ID, REPORT_LEADS_CHANNEL_ID, REPORT_LEADS_USER_TYPE } from "../action/types";

const initialState = {
    userType: "sales",
    channelId: null,
    companyId: null,
    brandId:null,
    currentChannel:null,
    startEndDate:{
        start:"",
        end:""
    }
}

const ReportLeadFilterRedux = (state = initialState, action) => {
    switch(action.type){
        case REPORT_LEADS_USER_TYPE:
            return {
                ...state,
                userType: action.value
            }
        case REPORT_LEADS_COMPANY_ID:
            return{
                ...state,
                companyId: action.value
            }
        case REPORT_LEADS_BRAND_ID:
            return {
                ...state,
                brandId:action.value
            }
        
        case REPORT_LEADS_CURRENT_CHANNEL:
            return {
                ...state,
                currentChannel: action.value
            }
        case REPORT_LEADS_START_END_DATE:
            return{
                ...state,
                startEndDate: action.value
            }
        case REPORT_LEADS_CHANNEL_ID:
            return {
                ...state,
                channelId:action.value
            }
        default:
            return state;
    }
}

export default ReportLeadFilterRedux