
export const checkUserType = (user, filBum, textButton) => {
    let isUserType = user?.data?.as.toLowerCase().split(" ").join("_");
    let valueFilterBum = filBum;
    if (
      isUserType?.toUpperCase() === "DIRECTOR" ||
      isUserType?.toUpperCase() === "BUM" ||
      isUserType?.toUpperCase() === "STORE_LEADER" ||
      isUserType?.toUpperCase() === "HS"
    ) {
      if (textButton?.toUpperCase()?.split(" ")?.join("_") === "STORE_LEADER") {
        isUserType = textButton?.toLowerCase();
      } else if (textButton?.toUpperCase() === "BUM") {
        isUserType = textButton.toLowerCase();
      } else if (textButton?.toUpperCase() === "STORE") {
        isUserType = textButton?.toLowerCase();
      } else if (textButton?.toUpperCase() === "SALES") {
        isUserType = textButton?.toLowerCase();
      } else if (textButton?.toUpperCase() === "HS") {
        isUserType = textButton?.toLowerCase();
      }
    }
    if (textButton?.toUpperCase() !== "SALES") {
      valueFilterBum = "";
    }
   
    return {isUserType, valueFilterBum}
  };