import React, { useState, useEffect } from 'react';
import { mainUrl } from '../../../../api/api';
import { connect } from 'react-redux';
import Button from '../../../../components/Button/Button';
import Axios from 'axios';
import { useHistory } from 'react-router-dom';
import LoadedComponent from '../../../../components/Loaded/LoadedComponent';
const FollowUpSeeDetails = ({prosesData: {dataFilterDate, idChannels, idCompany}}) => {
    const dataTables = [
        {
            thead: "No"
        },
        {
            thead: "Tanggal"
        },
        {
            thead: "Nama Customer"
        },
        {
            thead: "No Telepon"
        },
        {
            thead: "Email"
        },
        {
            thead: "Nama Sales"
        },
        {
            thead: "Company Name"
        }
    ]
    
    const [isLoading, setIsLoading] = useState(true);
    const [pagination, setPagination] = useState({
        page:1,
        meta:{}
    });
    const history = useHistory();
    const stateHistory = history?.location?.state;
    const [isData, setIsData] = useState([]);
    const [newFilterDate, setNewFilterDate] = useState({
        start:stateHistory?.formatDate?.start,
        end:stateHistory?.formatDate?.end
    });
    useEffect(() => {
        console.log("apakah mengalami looping")
        const config = {
            headers: {
              "Content-Type": "application/json",
              Authorization: `Bearer ${localStorage.token}`,
            },
        };
        if(stateHistory === null || stateHistory === undefined || stateHistory === ""){
            history.push("/dashboard");
        }
        const getDataFollowUp = () => {
            Axios.get(`${mainUrl}/leads/list?user_type=${stateHistory.typeUser}&id=${stateHistory?.data?.id}&start_date=${newFilterDate.start}&end_date=${newFilterDate.end}&activity_status=${stateHistory.statusActv}&page=${pagination.page}`, config)
            .then(res => {
                if(res.status === 200){
                    setIsLoading(false)
                    setIsData(res.data.data)
                    setPagination((prev) => ({
                        ...prev,
                        meta:res.data
                    }))
                }
            })
            .catch(error => console.log(error.response, "check error follow up"))
        }   

        getDataFollowUp()
    }, [pagination.page, stateHistory, newFilterDate, history]);
    const handleChangeDate = (e)=>{
        setIsLoading(true)
        setNewFilterDate(prev => {
            return{
                ...prev,
                [e.target.name]:e.target.value
            }
        })
    }
    const handleClickEventTable = (data,event) => {
        history.push({
            pathname:`/dashboard/customers/customer_detail/${data.id}/${data?.customer?.id}`,
            state:{idCustomer: data.customer.id}
        })
    }
    return(
        <>
            <div className='container'>
                <div style={{display: "flex", alignItems: "center", width:"40%"}}>
                    <input
                        type="date"
                        id="start"
                        name="start"
                        className="form-control"
                        placeholder="Start Month"
                        onChange={handleChangeDate}
                        value={dataFilterDate.start === undefined || dataFilterDate.start === null ? "" : dataFilterDate.start}
                        disabled
                    />
                    <div className="input-group-addon"style={{margin: "0 10px"}}>to</div>
                    <input
                        type="date"
                        id="end"
                        name="end"
                        className="form-control"
                        placeholder="End Month"
                        onChange={handleChangeDate}
                        style={{margin:"0"}}
                        value={dataFilterDate.end === undefined || dataFilterDate.end === null ? "" : dataFilterDate.end}
                        disabled
                    />
                </div>
                <h3 style={{margin:"20px 0"}}>{stateHistory.data.name} ({stateHistory?.statusActv})</h3>
                <div style={{display:"flex", gap: "20px"}}>
                   {pagination?.meta?.links?.prev !== null && <div >
                        <Button onClick={() => setPagination((prev) => ({
                            ...prev,
                            page: prev.page - 1
                        }))}icon="" title="Prev" style={{width:"11rem"}} btnStyle="primary-btn" />
                    </div>}
                    {pagination?.meta?.links?.next !== null && <div>
                        <Button onClick={() => setPagination((prev) => ({
                            ...prev,
                            page: prev.page + 1
                        }))}icon="" title="Next" style={{width:"11rem"}} btnStyle="primary-btn" />
                    </div>}
                    
                </div>
                {isData.length !== 0 && !isLoading ? (<table className="data " style={{ margin: "10px 0", overflowX: "scroll", width:"100%" }}>
                    <thead>
                        <tr>
                            {
                                dataTables.map((dat, inde) => {
                                    return (
                                        <th key={inde}>{dat.thead}</th>
                                    )
                                })
                            }
                        </tr>
                    </thead>
                    <tbody>
                        {
                            isData.length !== 0 && isData.map((dataList, inde) => {
                                return (
                                    <tr key={inde}  onClick={(e) => handleClickEventTable(dataList,e)}>
                                        <td>{pagination?.meta?.meta?.from + inde}</td>
                                        <td>{dataList.label}</td>
                                        <td>{dataList.customer.first_name} {dataList.customer.last_name}</td>
                                        <td>{dataList.customer.phone}</td>
                                        <td>{dataList.customer.email}</td>
                                        <td>{dataList.user.name}</td>
                                        <td>{dataList.channel.name}</td>
                                    </tr>
                                )
                            })
                        }
                    </tbody>
                </table>) : isData.length === 0 && !isLoading ?  (<h3 style={{marginTop: "50px"}}>Hasil Tidak Ditemukan</h3>) : <LoadedComponent />}
                {!isLoading && <Button onClick={(e) => history.goBack()}icon="" title="Back" style={{width:"11rem!important", marginTop:"30px"}} btnStyle={"primary-btn"} />}
                
            </div>
        </>
    )
}
const mapStateToProps = (state) => ({
    auth: state.auth,
    prosesData: state.prosesData
})
export default connect(mapStateToProps)(FollowUpSeeDetails)