import axios from "axios";
import moment from "moment";
import React, { useEffect, useState } from "react";
import { Link, useParams } from "react-router-dom";
import { mainUrl } from "../../api/api";
import { formatCurrency } from "../../api/format";
import { isValidate } from "../../lib/Validate";
import FilterLeadsReport from "../FilterForm/FilterLeadsReport";
import Header from "../Header/Header";
import LoadedComponent from "../Loaded/LoadedComponent";
import "./ReportBum.scss";

const ReportLeads = () => {
  const params = useParams();
  const { user_type, user_id, start, end } = params;
  const [reportData, setReportData] = useState(null);
  // filter
  const [filterCompany, setFilterCompany] = useState();
  const [filterChannels, setFilterChannels] = useState();
  const [filterSupervisior, setFilterSupervisor] = useState();
  const [filterDate, setFilterDate] = useState();
  const [filterStartDate, setFilterStartDate] = useState(
    params.start !== "now" ? params.start : localStorage.getItem("date_leads_start") !== undefined && localStorage.getItem("date_leads_start") !== null ?localStorage.getItem("date_leads_start")  : ""
  );
  const [filterEndDate, setFilterEndDate] = useState(params.end !== "now" ? params.end : localStorage.getItem("date_leads_end") !== undefined && localStorage.getItem("date_leads_end") !== null ? localStorage.getItem("date_leads_end"): "");
  useEffect(() => {
    const startDate = localStorage.getItem("date_leads_start")
        
    const endDate = localStorage.getItem("date_leads_end");
    if(startDate === undefined || startDate === null){
      localStorage.setItem("date_leads_start", params.start)
      if(endDate === undefined || endDate === null){
        localStorage.setItem("date_leads_end", params.end);
      }
     
    }
  },[params])
  const [isLoading, setIsLoading] = useState(false);
  useEffect(() => {
    const config = {
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${localStorage.token}`,
      },
    };
    const getReportBrands = async () => {
      setIsLoading(true);
      try {
        const res = await axios.get(
          `${mainUrl}/dashboard/report-leads/details?start_date=${
            filterStartDate ? moment(filterStartDate).format("YYYY-MM-DD") : ""
          }&end_date=${
            filterEndDate ? moment(filterEndDate).format("YYYY-MM-DD") : ""
          }&company_id=${filterCompany ? filterCompany : ""}&${
            user_type === "bum"
            ? "supervisor_id=" + parseInt(user_id)
            : user_type === "channel"
            ? "channel_id=" + parseInt(user_id)
            : user_type === "sales"
            ? "sales_id=" + parseInt(user_id)
            : ""
          }`,
          config
        );
        setReportData(res.data);
        setIsLoading(false);
      } catch (error) {
        console.error(error);
        setIsLoading(false);
      }
    };

    getReportBrands();
  }, [
    filterCompany,
    filterChannels,
    filterSupervisior,
    filterStartDate,
    filterEndDate,
    user_id,
    user_type,
  ]);
  return (
    <div>
      <Header icon="" title={`Report Leads`} back={true} user={false} />

      <FilterLeadsReport
        filterCompany={filterCompany}
        setFilterCompany={setFilterCompany}
        setFilterSupervisor={setFilterSupervisor}
        setFilterChannels={setFilterChannels}
        setFilterDate={setFilterDate}
        setFilterStartDate={setFilterStartDate}
        setFilterEndDate={setFilterEndDate}
        company={true}
        channel={true}
        supervisor={true}
      />
      {isLoading ? (
        <LoadedComponent />
      ) : (
        <div style={{ overflow: "scroll" }}>
          <table className="table-report" style={{ margin: "10px 0" }}>
            <thead style={{ textAlign: "center" }}>
              <tr>
                <th></th>
                <th colSpan="12">Total Leads</th>
              </tr>
              <tr>
                <th>Name</th>

                <th colSpan="4">Status</th>
                <th colSpan="3">Hot</th>
                <th colSpan="3">Closing Deals</th>
              </tr>
              <tr>
                <th></th>
                <th>Drop</th>
                <th>Cold</th>
                <th>Warm</th>
                <th>Hot</th>
                <th>ESTIMATED</th>
                <th>QUOTATION</th>
                <th>Action</th>

                <th>INVOICE PRICE</th>
                <th>AMOUNT PAID</th>
                <th>Action</th>
              </tr>
            </thead>
            {reportData &&
              reportData.map((data, idx) => {
                return (
                  <tbody key={idx}>
                    <tr>
                      <td>{data.name && data.name}</td>
                      <td>{data.drop_leads ? data.drop_leads : 0}</td>
                      <td>
                        <Link
                          to={`/dashboard/report/sales/${data.user_id}/cold/${
                            filterStartDate ? filterStartDate : "now"
                          }/${filterEndDate ? filterEndDate : "now"}/status`}
                        >
                          {data.cold}
                        </Link>
                      </td>
                      <td>
                        <Link
                          to={`/dashboard/report/sales/${data.user_id}/warm/${
                            filterStartDate ? filterStartDate : "now"
                          }/${filterEndDate ? filterEndDate : "now"}/status`}
                        >
                          {data.warm}
                        </Link>
                      </td>

                      <td>
                        <Link
                          to={`/dashboard/report/sales/${data.user_id}/hot/${
                            filterStartDate ? filterStartDate : "now"
                          }/${filterEndDate ? filterEndDate : "now"}/status`}
                        >
                          {data.hot}
                        </Link>
                      </td>
                      <td>
                        {!isValidate(data.estimated_value)
                          ? formatCurrency(data.estimated_value)
                          : "0"}
                      </td>
                      <td>
                        {data.quotation ? formatCurrency(data.quotation) : "0"}
                      </td>
                      <td>
                        <Link
                          to={`/dashboard/report/sales/${data.user_id}/hot/${
                            filterStartDate ? filterStartDate : "now"
                          }/${filterEndDate ? filterEndDate : "now"}`}
                        >
                          See Detail
                        </Link>
                      </td>

                      <td>
                        {data.invoice_price
                          ? formatCurrency(data.invoice_price)
                          : "0"}
                      </td>
                      <td>
                        {data.amount_paid
                          ? formatCurrency(data.amount_paid)
                          : "0"}
                      </td>
                      <td>
                        <Link
                          to={`/dashboard/report/sales/${data.user_id}/deal/${
                            filterStartDate ? filterStartDate : "now"
                          }/${filterEndDate ? filterEndDate : "now"}`}
                        >
                          See Detail
                        </Link>
                      </td>
                    </tr>
                  </tbody>
                );
              })}
          </table>
        </div>
      )}
    </div>
  );
};

export default ReportLeads;
