import axios from "axios";
import React, { useEffect, useState } from "react";
import { mainUrl } from "../../../api/api";

const Location = (props) => {
  const { item, i, handleAddLocation } = props;
  const [locations, setLocations] = useState([]);
  useEffect(() => {
    const config = {
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${localStorage.token}`,
      },
    };
    const getLocations = async () => {
      try {
        const res = await axios.get(
          `${mainUrl}/locations?sku=${item.sku}&company_id=1`,
          config
        );
        setLocations(res.data.stocks);
      } catch (error) {
        console.error(error);
      }
    };

    getLocations();
  }, [item.sku]);
  return (
    locations &&
    locations.length > 0 && (
      <select
        className="form-select"
        name="location"
        onChange={(e) => handleAddLocation(item, i, e.target.value)}
      >
        <option value="" selected hidden>
          Select Location
        </option>

        {locations &&
          locations.filter((d) => d.stock !== 0).map((data) => {
            return (
              <option value={data.orlan_id}>
                {data.name} / {data.stock}
              </option>
            );
          })}
      </select>
    )
  );
};

export default Location;
