import moment from "moment";
import React, { useState } from "react";
import { useParams, useHistory } from "react-router-dom";
import axios from "axios";
import { mainUrl } from "../../../api/api";
// import { isValidate } from "../../../lib/Validate";
import Button from "../../Button/Button";
import LoadingTableAllData from "../../Loaded/LoadingTableAllData";
import Header from "./ReportLeadsHead";
import { formatCurrency } from "../../../api/format";
// import Button from "../../Button/Button";
import useReportLeadDetailList from "../apiReportLeads/useReportLeadDetailList";
import ReportLeadsHeader from "./ReportLeadsHeader";
import { connect } from "react-redux";
import Activity from "../../ActivityDetail/Activity";
const ReportLeadsDetailHot = ({ReportLeadFilterRedux: {channelId, companyId, brandId, currentChannel, startEndDate, userType}}) => {
    const params = useParams();
    const history = useHistory();
    const historyState = history?.location?.state
    const { user_id, detail_type } = params;
    const [searchState, setSearchState] = useState({
        start: startEndDate.start === "" ? "2021-01-01" : startEndDate.start,
        end: startEndDate.end === "" ? moment(new Date()).format("YYYY-MM-DD") : startEndDate.end,
        channelId: channelId === null ? "" : channelId,
        companyId: companyId === null ? "" : companyId,
        brandId: brandId === null ? "" : brandId,
        userType: userType, 
        currentUserType: "",
        userId: user_id,
        status: detail_type,
        count: 1
    });
    const [customerActivity, setCustomerActivity] = useState(null);
    const [orderId, setOrderId] = useState(null);
    const [activityDetail, setActivityDetail] = useState(false);
    const { data:reportDataDetailHot, error, isLoading } = useReportLeadDetailList({searchState});
    const handleClickDetail = async (activity) => {
    try {
      const res = await axios.get(
        `${mainUrl}/activities?filter[id]=${activity?.activity?.id ?? ""}`,
        {
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${localStorage.token}`,
          },
        }
      );
      setCustomerActivity(res?.data?.data[0]);
      // console.log(res.data);
    } catch (error) {
      console.error(error);
    }
    setActivityDetail(!activityDetail);
    setOrderId(activity.activity ? activity.activity.order_id : null);
    // console.log(activity.activity);
  };
  if(isLoading){
    return <div className="">
            <Header
              icon=""
              title={`Report Leads - ${detail_type.toUpperCase()}`}
              back={true}
              user={false}
            />
            <ReportLeadsHeader 
                searchState={searchState}
                setSearchState={setSearchState}
                type="company"
                channel={false}
                company={false}
            />
            <LoadingTableAllData />        
          </div>
  }

  if(error){
    return <h4>Terjadi kesalahan pada server</h4>
  }

  return (
    <div>
      <Header
        icon=""
        title={`Report Leads - ${detail_type?.toUpperCase()}`}
        back={true}
        user={false}
      />

        <ReportLeadsHeader 
            searchState={searchState}
            setSearchState={setSearchState}
            user={historyState?.user ?? null}
            channel={false}
            company={false}
            type="type"
        />
      <div style={{ overflow: "scroll" }}>
          <table className="" style={{ margin: "10px 0" }}>
            <thead>
              <tr>
                <th>No.</th>
                <th>Date</th>
                <th>Name</th>
                  {/* <th>Sales</th> */}
                <th>Channel</th>
                <th>Quotation</th>
                <th>Status</th> 
                  {/* <th>Estimated Value</th> */}
                <th>Action</th>
              </tr>
            </thead>
            <tbody>
              {reportDataDetailHot &&
                reportDataDetailHot?.data?.map((data, idx) => {
                  return (
                    <tr key={idx}>
                        <td>{reportDataDetailHot.from + idx}</td>
                        <td>
                          {moment(data?.created_at).format(
                            "YYYY-MM-DD"
                          )}
                        </td>
                        <td>{data?.customer?.first_name ?? ""} {data?.customer?.last_name ?? ""}</td>
                        {/* <td>{data?.name}</td> */}
                        <td>{data?.channel?.name}</td>

                        <td>
                          {data.total_price && formatCurrency(data.total_price)}
                        </td>
                        <td>
                          {data.payment_status === "1" && "QUOTATION"}
                          {data.payment_status === "2" && "SHIPMENT"}
                          {data.payment_status === "5" && "CANCELLED"}
                          {data.payment_status === "6" && "RETURNED"}
                         
                        </td>
                        {/* <td>
                          {data.estimated_value &&
                            formatCurrency(data.estimated_value)}
                        </td> */}
                        <td>
                          <div
                            onClick={() => handleClickDetail(data)}
                            className="activity-detail-btn"
                          >
                            <img
                              src="/Asset/Action Icon/eye.png"
                              style={{ marginRight: "5px" }}
                              alt="eye"
                            />
                            See Detail
                          </div>
                        </td>
                    </tr>
                  );
                })}
            </tbody>
          </table>
            <div style={{display:"flex", gap:"20px", marginTop:"50px", alignItems:"center"}}>
                <div style={{display: reportDataDetailHot?.prev_page_url=== null ? "none" : "block"}}>
                    <Button
                        onClick={() => setSearchState((prev) => ({
                            ...prev,
                            count: prev.count === 1 ? 1 : prev.count - 1
                        }))}
                        icon=""
                        title={"Prev"}
                        style={{ width: "11rem!important"}}
                        btnStyle={"primary-btn"}
                    />
                </div>
                
                <div style={{display: reportDataDetailHot?.next_page_url === null ? "none" : "block"}}>
                <Button
                        onClick={() => {setSearchState((prev) => ({
                            ...prev,
                            count: prev.count + 1
                        }))}}
                        icon=""
                        title={"Next"}
                        style={{ width: "11rem!important", display: reportDataDetailHot?.links?.next === null ? "none" : "block"}}
                        btnStyle={"primary-btn"}
                    />
                </div>
            </div>
        </div>
        {customerActivity ? (
        <Activity
          activityDetail={activityDetail}
          setActivityDetail={setActivityDetail}
          customerActivity={customerActivity}
          orderId={orderId}
        />
      ) : (
        ""
      )}
    </div>
  );
};
const mapStateToProps = (state) => ({
    auth: state.auth,
    target: state.target,
    prosesData: state.prosesData,
    ReportLeadFilterRedux: state.ReportLeadFilterRedux,
  });
export default connect(mapStateToProps)(ReportLeadsDetailHot);
