import { ID_COMPANY, DATA_NEW_REPORTS, DATA_SEE_DETAILS, DATA_FILTER_DATE, ID_CHANNELS } from "../action/types";

const initialState = {
    idCompany: null,
    idChannels: null,
    idSupervisor: null,
    dataNewReports: [],
    dataSeeDetails: [],
    dataFilterDate: {
        start:"",
        end:""
    }
}

const ProsesData = (state = initialState, action) => {
    switch(action.type){
        case ID_COMPANY:
            return{
                ...state,
                idCompany: action.value
            }
        case DATA_NEW_REPORTS:
            return{
                ...state,
                dataNewReports: action.value
            }
        case DATA_SEE_DETAILS:
            return{
                ...state,
                dataSeeDetails: action.value
            }
        case DATA_FILTER_DATE:
            return{
                ...state,
                dataFilterDate: action.value
            }
        case ID_CHANNELS:
            return {
                ...state,
                idChannels:action.value
            }
        default:
            return state;
    }
}

export default ProsesData