import axios from "axios";
import moment from "moment";
import React, { useEffect, useState } from "react";
import ReactPaginate from "react-paginate";
import { useParams } from "react-router-dom";
import { mainUrl } from "../../../api/api";
import Header from "../../../components/Header/Header";
import LoadedComponent from "../../../components/Loaded/LoadedComponent";

const ActivityCount = () => {
  const { company_id, month } = useParams();

  const [filterMonth, setFilterMonth] = useState(month);
  const [salesEstimationData, setSalesEstimationData] = useState(null);
  const [isLoading, setIsLoading] = useState(false);

  // Pagination
  const [page, setPage] = useState(0);
  const [pageData, setPageData] = useState(0);

  useEffect(() => {
    const getData = async () => {
      setIsLoading(true);
      const config = {
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${localStorage.token}`,
        },
      };
      try {
        const res = await axios.get(
          `${mainUrl}/activities/report/detail?company_id=${company_id}&start_at=${moment(
            filterMonth
          )
            .startOf("month")
            .format("YYYY-MM-DD")}&end_at=${moment(filterMonth)
            .endOf("month")
            .format("YYYY-MM-DD")}&page=${page}`,
          config
        );
        setSalesEstimationData(res.data.data);
        setPageData(res.data);
        setIsLoading(false);
      } catch (error) {
        setIsLoading(false);
      }
    };
    getData();
  }, [company_id, filterMonth, page]);

  const handlePageClick = (data) => {
    setPage(data.selected + 1);
  };

  return (
    <div>
      <Header title={`Activity Count`} back={true} notif={true} />
      <div className="filter-form d-flex justify-content-between">
        <div>
          <input
            type="month"
            id="start"
            name="start"
            className="form-control"
            placeholder="Start Month"
            value={filterMonth}
            onChange={(e) => setFilterMonth(e.target.value)}
            style={{ height: "41px" }}
          />
        </div>
      </div>

      {!isLoading ? (
        <div className="mt-4">
          <table className="data" style={{ margin: "10px 0" }}>
            <thead>
              <tr>
                <th>No</th>
                <th>Name</th>
                <th>Channel</th>
                <th>Total Activity</th>
              </tr>
            </thead>
            <tbody>
              {salesEstimationData &&
                salesEstimationData.map((data, i) => {
                  return (
                    <tr key={i}>
                      <td>{pageData.from + i}</td>
                      <td>{data.name}</td>
                      <td>{data.channel}</td>
                      <td>{data.total_activities}</td>
                    </tr>
                  );
                })}
            </tbody>
          </table>
        </div>
      ) : (
        <LoadedComponent />
      )}
      {pageData.last_page && (
        <div>
          <ReactPaginate
            previousLabel={"Prev"}
            nextLabel={"Next"}
            breakLabel={"..."}
            pageCount={pageData.last_page}
            marginPagesDisplayed={3}
            onPageChange={handlePageClick}
            containerClassName={"pagination"}
            pageClassName={"page-item"}
            pageLinkClassName={"page-link"}
            previousClassName={"page-item"}
            previousLinkClassName={"page-link"}
            nextClassName={"page-item"}
            nextLinkClassName={"page-link"}
            breakClassName={"page-item"}
            breakLinkClassName={"page-link"}
            activeClassName={"active"}
          />
        </div>
      )}
    </div>
  );
};

export default ActivityCount;
