import axios from "axios";
import moment from "moment";
import React, { useEffect, useState } from "react";
import { useParams } from "react-router-dom";
import { mainUrl } from "../../../api/api";
import Header from "../../../components/Header/Header";
import LoadedComponent from "../../../components/Loaded/LoadedComponent";
import { isValidate } from "../../../lib/Validate";
import ApprovalDetail from "./ApprovalDetail";

const Approval = () => {
  const params = useParams();
  const { approval_type } = params;
  const [dataApproval, setDataApproval] = useState();
  const [isLoading, setIsLoading] = useState(false);
  const [refresh, setRefresh] = useState(false);
  const [activityDetail, setActivityDetail] = useState(false);
  const [dataOrder, setDataOrder] = useState();

  //   filter
  const [search, setSearch] = useState("");

  // Pagination
  const [page, setPage] = useState(0);
  const [pageData, setPageData] = useState(0);
  useEffect(() => {
    const getData = async () => {
      setIsLoading(true);
      try {
        const res = await axios.get(
          `${mainUrl}/orders/list-approval?filter[approval_status]=${
            approval_type !== "ALL" ? approval_type : ""
          }&filter[search]=${search}&perPage=100`,
          {
            headers: {
              "Content-Type": "application/json",
              Authorization: `Bearer ${localStorage.token}`,
            },
          }
        );
        setDataApproval(res.data);
        setPageData(res.data.meta);
        setIsLoading(false);
      } catch (error) {
        console.log(error);
        setIsLoading(false);
      }
    };

    getData();
  }, [approval_type, search, refresh, page]);

  const handlePageClick = (data) => {
    setPage(data.selected + 1);
  };

  const handleClickDetail = async (activity) => {
    setActivityDetail(!activityDetail);
    setDataOrder(activity);
  };

  return (
    <div>
      {dataOrder && (
        <ApprovalDetail
          data={dataOrder}
          activityDetail={activityDetail}
          setActivityDetail={setActivityDetail}
          refresh={refresh}
          setRefresh={setRefresh}
        />
      )}

      <Header
        title={`Discount Approval - ${
          approval_type === "WAITING_APPROVAL"
            ? "NEED MY APPROVAL"
            : approval_type
        }`}
      />
      <div>
        <div>
          <input
            type="text"
            id="search-sales"
            name="search-sales"
            className="form-control"
            placeholder="Search customer name/inv number"
            onChange={(e) => setSearch(e.target.value)}
            style={{ height: "41px", width: "327px" }}
          />
        </div>
      </div>
      {isLoading ? (
        <LoadedComponent />
      ) : (
        <div>
          <table style={{ position: "relative", overflow: "unset" }}>
            <thead style={{ position: "sticky", top: "20px", zIndex: "20" }}>
              <tr>
                <th>No.</th>
                <th>Name</th>
                <th>Date</th>
                <th>Invoice</th>
                <th>Channel</th>
                <th>Sales</th>
                <th>Action</th>
              </tr>
            </thead>
            <tbody style={{ zIndex: "0" }}>
              {dataApproval &&
                dataApproval.data.map((d, idx) => {
                  return (
                    <tr key={d.id}>
                      <td>{idx + 1}</td>
                      <td>{`${
                        d.customer.first_name && d.customer.first_name
                      }  ${
                        !isValidate(d.customer.last_name)
                          ? d.customer.last_name
                          : ""
                      }`}</td>
                      <td>
                        {moment(d.updated_at).format("DD MMMM YYYY, HH:MM")}
                      </td>
                      <td>{d.invoice_number}</td>
                      <td>{d.channel.name}</td>
                      <td>{d.user.name}</td>
                      <td>
                        <div
                          onClick={() => handleClickDetail(d)}
                          className="activity-detail-btn"
                        >
                          <img
                            src="/Asset/Action Icon/eye.png"
                            style={{ marginRight: "5px" }}
                            alt="eye"
                          />
                          See Detail
                        </div>
                      </td>
                    </tr>
                  );
                })}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
};

export default Approval;
