import React, { useEffect } from 'react';
import { formatCurrency } from '../../../../api/format';
import { directToNextPage } from '../funcSeeDetails/directToNextPage';
const TableReport = ({dataDetails, newFilterDate, textButton, user, history}) => {
    const handleClickEventTable = (data, event) => {
        directToNextPage(data, event, newFilterDate, textButton, user, history)
    }
    return (
        <>
            <thead>
                <tr>
                    <th>No</th>
                    {/* <th className='sticky' style={{position:"sticky", left:"0"}}>Name</th> */}
                    <th>Name</th>
                    <th>Deals</th>
                    <th>New Leads</th>
                    <th>Interior Design</th>
                    <th>Retails</th>
                    <th>Active Leads</th>
                    <th>Quotation</th>
                    <th>Pipelines</th>
                    <th>Follow Up</th>
                    <th>Hot</th>
                    <th>Warm</th>
                    <th>Cold</th>
                </tr>
            </thead>
            <tbody>
              {dataDetails?.map((data, i) => {
                return (
                  <tr key={i} onClick={(e) => handleClickEventTable(data, e)}>
                    <td>{i + 1}.</td>
                    {/* <td
                      className="sticky"
                      style={{ position: "sticky", left: "0" }}
                    >
                      {data?.name}
                    </td> */}
                    <td>{data.name}</td>
                    <td style={{ cursor: "pointer" }} data-status-type="deals">
                      {formatCurrency(data.deals.value, true).replace(
                        /([A-Za-z])\w+/g,
                        ""
                      )}
                    </td>
                    <td
                      style={{ cursor: "pointer" }}
                      data-status-type="new-leads"
                    >
                      {data.new_leads.value}
                    </td>
                    <td
                      style={{ cursor: "pointer" }}
                      data-status-type="interior-design"
                    >
                      {formatCurrency(data.interior_design.value, true).replace(
                        /([A-Za-z])\w+/g,
                        ""
                      )}
                    </td>
                    <td style={{ cursor: "pointer" }} data-status-type="retail">
                      {formatCurrency(data.retail.value, true).replace(
                        /([A-Za-z])\w+/g,
                        ""
                      )}
                    </td>
                    <td
                      style={{ cursor: "pointer" }}
                      data-status-type="active-leads"
                    >
                      {data.active_leads.value}
                    </td>
                    <td
                      style={{ cursor: "pointer" }}
                      data-status-type="quotation"
                    >
                      {formatCurrency(data.quotation.value, true).replace(
                        /([A-Za-z])\w+/g,
                        ""
                      )}
                    </td>
                    <td
                      style={{ cursor: "pointer" }}
                      data-status-type="pipelines"
                    >
                      {formatCurrency(data.estimation.value, true).replace(
                        /([A-Za-z])\w+/g,
                        ""
                      )}
                    </td>
                    <td style={{cursor:"pointer"}}onClick={() => history.push(`/dashboard/follow-up-activities/status/${data?.id}${newFilterDate.start !== "" ? "/" + newFilterDate.start : ""}${newFilterDate.end !== "" ? "/" + newFilterDate.end : ""}`)}>{data.total_leads.value}</td>
                    <td style={{ cursor: "pointer" }} data-status-type="HOT">
                      {data.follow_up.hot_activities}
                    </td>
                    <td style={{ cursor: "pointer" }} data-status-type="WARM">
                      {data.follow_up.warm_activities}
                    </td>
                    <td style={{ cursor: "pointer" }} data-status-type="COLD">
                      {data.follow_up.cold_activities}
                    </td>
                  </tr>
                );
              })}
            </tbody>
        </>
    )
} 

export default TableReport
