import React, { useEffect, useState, useMemo } from "react";
import { isFilterDate } from "../../../redux/action/idUser";
import { useHistory, useParams } from "react-router-dom";
import LoadedComponent from "../../../components/Loaded/LoadedComponent";
import HeadDashboardSeeDetail from "./DashboardSeeDetail/HeadDashboardSeeDetail";
import TableSeeDetail from "./DashboardSeeDetail/TableSeeDetail";
import { useDispatch } from "react-redux";
import XLSX from "xlsx-js-style"
import { connect } from "react-redux";
import { useUserList } from "./api/useUsersList";
const DashboardSeeDetail = ({auth: {user}, prosesData: {dataFilterDate, idChannels, idCompany}}) => {

  const history = useHistory()
  const {userType} = useParams();
  const dispatch = useDispatch();
  const [dataExport, setDataExport] = useState(null)
  const [pagination, setPagination] = useState({
    limit: 10
  })
  const [searchState, setSearchState] = useState({
    userType: userType === "director" 
    ? "hs" 
    : userType === "hs" 
      ? "bum" 
      : userType === "bum" 
        ? "store_leader" 
        : userType === "store_leader" 
          ? "sales" 
          : "",
    companyId: "",
    searchValue:"",
    start: dataFilterDate.start === undefined ? "" : dataFilterDate.start,
    end: dataFilterDate.end === undefined ? "" : dataFilterDate.end,
    userFilter:null,
    channelId: idChannels === undefined || idChannels === null ? "" : idChannels,
    onTouch: false
  });

  const [filterOnTouch, setFilterOnTouch] = useState({
    userType: userType === "director" 
              ? "hs" 
              : userType === "hs" 
                ? "bum" 
                : userType === "bum" 
                  ? "store_leader" 
                  : userType === "store_leader" 
                    ? "sales" 
                    : "",
    companyId: "",
    searchValue:"",
    start: dataFilterDate.start === undefined ? "" : dataFilterDate.start,
    end: dataFilterDate.end === undefined ? "" : dataFilterDate.end,
    userFilter:null,
    channelId: idChannels === undefined || idChannels === null ? "" : idChannels
  });


  const roleButton = useMemo(() => (
    {
      director: ["Head Sales", "Bum", "Store Leader", "Store", "Sales"],
      hs: ["Bum", "Store Leader", "Store" ,"Sales"],
      bum: ["Store Leader", "Store", "Sales"],
      store_leader:["Store", "Sales"],
      store: ["Sales"]
    }
  ), [])
  const {data:dataUserList, isLoading:loadingUser, error} = useUserList({filterOnTouch});

  const spliceUsers = useMemo(() => {
    return dataUserList?.details?.slice(0, pagination.limit)
  }, [dataUserList, pagination]);
  useMemo(() => {
    if(searchState.onTouch){
      dispatch(isFilterDate(searchState))
    }
    searchState.onTouch && setFilterOnTouch((prev) => ({
      ...prev,
      userType: searchState.userType,
      companyId: searchState.companyId,
      searchValue: searchState.searchValue,
      start: searchState.start,
      end: searchState.end,
      userFilter:null,
    }));

    
  }, [searchState, dispatch]);

  useEffect(() => {
    
    if(user?.data?.as?.split(" ")?.join("_")?.toLowerCase() !== userType && user !== undefined){
      history.push(`/dashboard/dashboard-see-detail/${user?.data?.id}/${user?.data?.as?.split(" ")?.join("_")?.toLowerCase()}`)
    }
  }, [userType, history, user]);
  
  useEffect(() => {
    searchState.onTouch && setSearchState((prev) => ({
      ...prev,
      onTouch:false
    }))
  }, [searchState]);

  const stylingXlsx = ({color, worksheet, cellRef}) => {
    worksheet[cellRef].s = {
      ...worksheet[cellRef].s,
      font: {
        sz: 14
      },
      fill:{
        type: 'pattern',
        pattern: 'solid',
        fgColor: { rgb: color }
      },
      border: {
        top: {style: "thin", color: {auto: 1}},
        right: {style: "thin", color: {auto: 1}},
        bottom: {style: "thin", color: {auto: 1}},
        left: {style: "thin", color: {auto: 1}}
      }
    }
  }
  const handleExportButton = () => {
    // console.log(dataExport, "checking data export yah heheheh")
     const resArrDataExp = dataExport.map((data, i) => {
        
            return {
                "No":i + 1,
                "Name": data.name,
                "Deals": data?.deals,
                "Retails": data?.retails,
                "Interior Design": data?.interiorDesign,
                "Exhibition": data.exhibition,
                "Quotation": data.quotation,
                "Pipelines": data.pipelines,
                "Follow Up": data.followUp,
                "Active Leads": data.activeLeads,
                "New Leads": data?.newLeads,
                "Hot": data.hot,
                "Warm": data.warm,
                "Drop":data?.drop ?? 0,
                "Cold": data.cold
            }
        });
        const workbook = XLSX.utils.book_new();
        const worksheet = XLSX.utils.json_to_sheet(resArrDataExp);
        const range = XLSX.utils.decode_range(worksheet["!ref"] ?? "");
        const rowCount = range.e.r;
        const columnCount = range.e.c;
        var wscols = [
          {wch:10},
          {wch:25},
          {wch:25},
          {wch:25},
          {wch:25},
          {wch:25},
          {wch:25},
          {wch:25},
          {wch:25},
          {wch:25},
          {wch:25},
          {wch:25},
          {wch:25},
          {wch:25},
        ];
      
        worksheet['!cols'] = wscols;
        for (let row = 0; row <= rowCount; row++) {
            for (let col = 0; col <= columnCount; col++) {
              const cellRef = XLSX.utils.encode_cell({ r: row, c: col });
              // Add center alignment to every cell
              worksheet[cellRef].s = {
                alignment: { horizontal: "center" },
              };
              if(row === 0){
                worksheet[cellRef].s = {
                  ...worksheet[cellRef].s,
                  font: {
                    bold: true,
                    sz: 16,
                    color: {rgb: "00000"}
                  },
                  
                }
              }
              if(row !== 0){
                if(col === 0 || col === 1){
                  stylingXlsx({
                    worksheet,
                    cellRef,
                    color:"ffffffff"
                  })
                }
                if(col > 1 && col < 6){
                  stylingXlsx({
                    worksheet,
                    cellRef,
                    color:"ff4ca6c1"
                  })
                }
                if(col > 8){
                  stylingXlsx({
                    worksheet,
                    cellRef,
                    color:"ffacdd6e"
                  })
                }
                if(col === 8){
                  stylingXlsx({
                    worksheet,
                    cellRef,
                    color:"ff94d244"
                  })
                }
                if(col === 6 || col === 7){
                  stylingXlsx({
                    worksheet,
                    cellRef,
                    color:"ff5fc1de"
                  })
                }
              }
            }
          }
        // Logic for manipulating worksheet

        XLSX.utils.book_append_sheet(workbook, worksheet, "sheet_name_here");
        XLSX.writeFile(workbook, `reports.xlsx`);
  }
  if(loadingUser){
    return <LoadedComponent/>
  }
  if(error){
    return <h4>Terjadi kesalahan</h4>
  }
  return (
    <div className="container">
      <HeadDashboardSeeDetail 
          setSearchState={setSearchState} searchState={searchState} suggestUsers={dataUserList?.details}
        />
        <div style={{display:"flex", gap:"30px", justifyContent:"space-around", margin: "40px 0"}}>
          {roleButton[user?.data?.as?.toLowerCase()?.split(" ")?.join("_")]?.map((role, idx) => {
            return (
              <React.Fragment key={idx}>
                
                <button 
                  onClick={() => {
                    setDataExport(null)
                    setPagination((prev) => ({...prev, limit:10}))
                    setSearchState((prev) => ({...prev, userType: role?.split(" ")?.join("_")?.toLowerCase() === "head_sales" ? "hs" : role?.split(" ")?.join("_")?.toLowerCase(), onTouch: true}))
                  }}
                  style={{
                    outline: "none",
                    background: role?.split(" ")?.join("_")?.toLowerCase() === searchState.userType ? "#20b5c0" : role?.split(" ")?.join("_")?.toLowerCase() === "head_sales" && searchState.userType === "hs" ? "#20b5c0" : "#17949d",
                    padding: "10px 30px",
                    borderRadius: "5px",
                    color:"white",
                    border:"0",
                  }}
                >
                  {role}
                </button>
              </React.Fragment>
            )
          })}
          
        </div>
        {/* <TableSeeDetail searchState={searchState} users={spliceUsers} dataUsers={dataUserList}/> */}
        {<button style={{border:"0", outline:"0", padding:"10px 20px", borderRadius:"5px", background:"#17949d", color:"white"}} onClick={handleExportButton}>Export</button>}
        <table
          className="data d-block"
          style={{ margin: "10px 0", overflowX: "scroll", width: "auto", position:"relative" }}
        >
          <thead>
            <tr>
              <th>No</th>
              {/* <th className='sticky' style={{position:"sticky", left:"0"}}>Name</th> */}
              <th>Name</th>
              <th>Deals</th>
              <th>New Leads</th>
              <th>Interior Design</th>
              <th>Retails</th>
              <th>Active Leads</th>
              <th>Quotation</th>
              <th>Pipelines</th>
              <th>Exhibition</th>
              <th>Follow Up</th>
              <th>Hot</th>
              <th>Warm</th>
              <th>Cold</th>
              <th>Drop</th>
            </tr>
          </thead>
          <tbody onClick={() => {}}>
            {
              searchState.searchValue !== "" && searchState.userFilter !== null && searchState.userFilter?.length !== 0 && searchState?.userFilter?.map((user,i) => {
                return (
                  <React.Fragment key={i}>
                    <TableSeeDetail searchState={filterOnTouch} isUser={user} dataUsers={dataUserList} index={i} setDataExport={setDataExport}/>
                  </React.Fragment>)
              })
            }
            {
              searchState.searchValue === "" || searchState.userFilter === null || searchState.userFilter?.length === 0 ? spliceUsers.map((user,i) => {
                return (
                  <React.Fragment key={i}>
                    <TableSeeDetail searchState={filterOnTouch} isUser={user} dataUsers={dataUserList} index={i} setDataExport={setDataExport}/>
                  </React.Fragment>)
              })
              : null
            }
          </tbody>
        </table>
        {pagination.limit < dataUserList?.details?.length && pagination.limit !== dataUserList?.details?.length && <button 
          onClick={() => setPagination((prev) => ({...prev, limit: prev.limit + 10}))}
          style={{
            outline: "none",
            background:"#17949d",
            padding: "10px 30px",
            borderRadius: "5px",
            color:"white",
            border:"0",
          }}
        >
          Load More
        </button>}
    </div>
  )
}


const mapStateToProps = (state) => ({
  auth: state.auth,
  target: state.target,
  prosesData: state.prosesData
});

export default connect(mapStateToProps)(DashboardSeeDetail)