import { useState } from "react";
import { connect } from "react-redux";
import useReportLeadList from "./apiReportLeads/useReportLeadList";
import TableReportLeadsStoreLeader from "./container/TableReportLeadsStoreLeader";
import ReportLeadsHeader from "./container/ReportLeadsHeader";
import TableReportLeads from "./container/TableReportLeads";
import LoadingTableAllData from "../Loaded/LoadingTableAllData";
import FooterTotalReports from "./container/FooterTotalReports";
import Button from "../Button/Button";
import { isValidate } from "../../lib/Validate";
import { formatCurrency } from "../../api/format";
import * as XLSX from "xlsx";
const ReportLeadSingle = ({ReportLeadFilterRedux: {channelId, companyId, brandId, currentChannel, startEndDate, userType}, auth: {user}}) => {
    // console.log(user, "check data user login",channelId, companyId, brandId, currentChannel, startEndDate, userType)
    const [searchState, setSearchState] = useState({
        start: startEndDate.start,
        end: startEndDate.end,
        channelId: channelId === null ? "" : channelId,
        companyId: companyId === null ? "" : companyId,
        brandId: brandId === null ? "" : brandId,
        userType: userType,
        supervisorsList: null,
        brandsList: null,
        currentUserType: ""
    });
  
    const { data, isLoading, error } = useReportLeadList({searchState});
    // const data = null;
    // const isLoading = true;
    // console.log( "checking loadingnya yah")
    const exportReportLeads = async (data) => {
        let resArrDataExp = [];
        data?.data?.forEach((data,i) => {
          let newObj = {}
          newObj["Name"] = data?.name;
          newObj["Drop"] = data?.drop_leads;
          newObj["Cold"] = data?.cold_activity;
          newObj["Warm"] = data?.warm_activity;
          newObj["Estimated"] = !isValidate(data.estimated_value) ? formatCurrency(data.estimated_value) : "0"
          newObj["HotNumberofLeads"] = data?.hot_activity;
          newObj["Quotation"] = !isValidate(data.quotation) ? formatCurrency(data.quotation) : "0" 
          newObj["DealNumberofLeads"] = data?.deal_leads
          newObj["Invoice"] = !isValidate(data.invoice_price) ? formatCurrency(data.invoice_price) : "0" 
          newObj["AmountPaid"] = !isValidate(data.amount_paid) ? formatCurrency(data.amount_paid) : "0" 
          resArrDataExp.push(newObj)
        });
        resArrDataExp.push({
          Name: "Total",
          Drop: data?.total?.drop_leads,
          Cold: data?.total?.cold_activity,
          Warm: data?.total?.warm_activity,
          Estimated: formatCurrency(data?.total?.estimated_value),
          HotNumberofLeads: data?.total?.hot_activity,
          Quotation: formatCurrency(data?.total?.quotation),
          DealNumberofLeads: data?.total?.deal_leads,
          Invoice: formatCurrency(data?.total?.invoice_price),
          AmountPaid: formatCurrency(data?.total?.amount_paid)
        })
        const wb = XLSX.utils.book_new();
            const ws = XLSX.utils.json_to_sheet(resArrDataExp);
            XLSX.utils.book_append_sheet(wb, ws, "report-leads");
            XLSX.writeFile(wb, "report-leads.xlsx");
      };
      if(error){
        return (<h4>Terjadi kesalahan pada server</h4>)
      }
    if(isLoading){
        return <div className="container">
                    <ReportLeadsHeader 
                        searchState={searchState}
                        setSearchState={setSearchState}
                        type="company"
                        user={user}
                    />
                    <LoadingTableAllData />        
                </div>
    }
    return (
        <>
            <div className="container">
                <ReportLeadsHeader 
                    searchState={searchState}
                    setSearchState={setSearchState}
                    type="company"
                    user={user}
                    isFetch={true}
                />
                <Button onClick={exportReportLeads}
     icon=""
           title="Export"
           style={{ width: "11rem!important" }}
           btnStyle={"primary-btn"}
     ></Button>
                <table
                    className="table-report"
                    style={{
                      margin: "10px 0",
                      position: "relative",
                      overflow: "unset",
                    }}
                >

                    <thead
                    style={{
                        textAlign: "center",
                        position: "sticky",
                        top: "20px",
                        zIndex: "20",
                    }}
                    >
                        <tr>
                            <th colSpan="2"></th>
                            <th colSpan="12">Total Leads</th>
                        </tr>
                        <tr>
                            <th colSpan="2">User</th>
                            <th className="leadshead"></th>
                            <th colSpan="4">Status</th>
                            <th colSpan="3">Hot</th>
                            <th colSpan="4">Closing Deals</th>
                        </tr>
                        <tr>
                            <th>Name</th>
                            <th style={{borderLeft:"0",borderBottom:"1px solid #17949d"}}></th>
                            <th className="">-</th>
                            <th>Drop</th>
                            <th>Cold</th>
                            <th>Warm</th>
                            <th>ESTIMATED</th>
                            <th>No of LEADS</th>

                            <th>QUOTATION</th>
                            <th>Action</th>
                            <th>No of LEADS</th>
                            <th>INVOICE PRICE <br/><span style={{fontSize:"10px"}}>* Tidak termasuk PPN</span></th>
                            <th>AMOUNT PAID</th>
                            <th>Action</th>
                        </tr>
                    </thead>
                   
                   {
                    data && data?.data?.map((data) => {
                        return user?.data?.as?.toLowerCase()?.split(" ")?.join("_") === "store_leader" 
                        ? <TableReportLeadsStoreLeader searchState={searchState} data={data}/>
                        : <TableReportLeads searchState={searchState} setSearchState={setSearchState}data={data} user={user}/>
                    })
                   }
                    <FooterTotalReports reportData={data} />
                </table>
            </div>
        </>
    )
}
const mapStateToProps = (state) => ({
    auth: state.auth,
    target: state.target,
    prosesData: state.prosesData,
    ReportLeadFilterRedux: state.ReportLeadFilterRedux,
  });
export default connect(mapStateToProps)(ReportLeadSingle)