export const formatCurrency = (numb, rm = false) => {
  const format = !rm ? numb?.toString()?.split("")?.reverse()?.join("") : truncNumb(numb)
  const convert = format?.match(/\d{1,3}/g);
  const rupiah = "Rp " + convert?.join(".")?.split("")?.reverse()?.join("");

//   console.log(rupiah);
  return rupiah;
};

const truncNumb = (numb) => {
  return Math?.trunc(numb)?.toString()?.split("")?.reverse()?.join("")
};
