import React, { useEffect, useState } from 'react';
import { connect } from 'react-redux';
import LoadedComponent from '../../../../components/Loaded/LoadedComponent';
import moment from 'moment';
import Button from '../../../../components/Button/Button';
import Axios from 'axios'
import { useHistory } from 'react-router-dom';
import { mainUrl } from '../../../../api/api';
import { formatCurrency } from '../../../../api/format';
const InteriorDesignSeeDetails = ({auth: {user}, prosesData: {dataFilterDate, idChannels, idCompany}}) => {
    const config = {
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${localStorage.token}`,
        },
    };
    const history = useHistory();
    const stateHistory = history?.location?.state
    const [isData, setIsData] = useState([]);
    const [isLoading, setIsLoading] = useState(true);
    const [newFilterDate,setNewFilterDate] = useState({
        start:stateHistory?.formatDate?.start,
        end:stateHistory?.formatDate?.end
    });
    const [searchValue, setSearchValue] = useState("");
    const [dataSearch, setDataSearch] = useState([]);
    const [filterButton, setFilterButton] = useState(false)
    useEffect(() => {
        const getDataFetching = async () => {
            Axios.get(`${mainUrl}/new-reports/interior-designs?id=${stateHistory?.data?.id}&user_type=${stateHistory?.typeUser}&start_date=${newFilterDate.start}&end_date=${newFilterDate.end}`, config)
            .then(res => {
                if(res.status === 200){
                    setIsLoading(false);
                    setFilterButton(false);
                    return setIsData(res.data)
                }
                setIsData([])
            })
            .catch(error => console.log(error.response, "chek error interior design"))
        }
        getDataFetching()
    }, [filterButton, history]);

    useEffect(() => {
        const searchName = () => {
            let newRes = isData.filter((mData,i) => {
                if(mData.interior_design.toUpperCase().indexOf(searchValue.toUpperCase()) >= 0){
                    return mData
                }
            })
            setDataSearch(newRes)  
        }

        isData.length !== 0 && searchName()
    }, [searchValue, isData])
    const handleChangeSearch = (e) => {
        setSearchValue(e.target.value)
    }
    const handleChangeDate = (e) => {
        setNewFilterDate(prev => {
            return{
              ...prev,
              [e.target.name]: e.target.value
            }
        })
    }
    const handleClickDetailInterior = (data) => {
        const stateHistory = history?.location?.state
        history.push({
            pathname: '/dashboard/see-details/interior-design/detail',
            state:{
                data: data,
                userType: history?.location?.state?.typeUser,
                dataForBack: stateHistory,
                formatDate: newFilterDate
            }
        });
    }   
    return(
        <>
            <div className='container'>
                <div className='filter d-flex' style={{gap:"20px"}}>
                    <div className="col-auto" style={{gap:"20px"}}>
                        <div >
                            <input type="text" id="search-table" className="form-control" onChange={handleChangeSearch}  placeholder='Search' value={searchValue} />
                        </div>
                    </div>
                    <div style={{display: "flex", alignItems: "center"}}>
                        <input
                            type="date"
                            id="start"
                            name="start"
                            className="form-control"
                            placeholder="Start Month"
                            value={dataFilterDate.start === undefined || dataFilterDate.start === null ? "" : dataFilterDate.start}
                            onChange={handleChangeDate}
                            disabled
                        />
                        <div className="input-group-addon"style={{margin: "0 10px"}}>to</div>
                        <input
                            type="date"
                            id="end"
                            name="end"
                            className="form-control"
                            placeholder="End Month"
                            value={dataFilterDate.end === undefined || dataFilterDate.end === null ? "" : dataFilterDate.end}
                            onChange={handleChangeDate}
                            style={{margin:"0"}}
                            disabled
                        />
                    </div>
                    <Button onClick={(e) => {
                        setFilterButton(true);
                        setIsLoading(true);
                    }}icon="" title="Filter" style={{width:"11rem!important", marginTop:"30px"}} btnStyle={"primary-btn"} />
                </div>
                <div className='title-list' style={{display: isLoading && isData.length === 0 ? "none" : "block"}}>
                    <h3 style={{marginTop: "50px"}}>List of Interior Design ({dataSearch.length})</h3>
                </div>
                {dataSearch.length !== 0 && !isLoading ? (<table className="data" style={{ margin: "10px 0", overflowX: "scroll", width:"100%" }}>
                        <thead>
                            <tr>
                                <th>No</th>
                                <th>Id Name</th>
                                <th>Revenue</th>
                            </tr>
                        </thead>
                        <tbody>
                            {dataSearch.map((data, i) => {
                            return (
                                <tr key={i} onClick={() => handleClickDetailInterior(data)}>
                                    <td style={{cursor: "pointer"}}>{i + 1}</td>
                                    <td style={{cursor: "pointer"}}>{data.interior_design}</td>
                                    <td style={{cursor: "pointer"}}>{formatCurrency(data.revenue, true).replace(/([A-Za-z])\w+/g, '')}</td>
                                </tr>
                            );
                            })}
                        </tbody>
                </table>) : isLoading ? <LoadedComponent /> : isData.length === 0 && (<h4>Hasil Tidak Ditemukan</h4>)  
                }
                {!isLoading && <Button onClick={(e) => history.push(`${user?.data?.as.toUpperCase() === "SALES" ? "/dashboard" :history.goBack()}`)}icon="" title="Back" style={{width:"11rem!important", marginTop:"30px"}} btnStyle={"primary-btn"} />}
            </div>
        </>
    )
}
const mapStateToProps = (state) => ({
    auth: state.auth,
    prosesData: state.prosesData
})
export default connect(mapStateToProps)(InteriorDesignSeeDetails)