import { useQuery } from "react-query";
import axios from "axios";
import { mainUrl,config } from "./api";
const useLeadsList = ({searchState,type}) => {
    return useQuery(["leadsList", searchState, type], () => {
        return axios.get(`${mainUrl}/leads?filter[type]=${type}&filter[customer_search]=${searchState.search ?? ""}&filter[user_id]=${searchState?.id ?? ""}`, config)
                .then((res) => res.data)
                .catch((error) => error)
    }, {refetchOnWindowFocus: (query) => query.state.status !== "error", staleTime:Infinity})
}


export default useLeadsList;


