import axios from "axios";
import moment from "moment";
import React, { Fragment, useEffect, useState } from "react";
import { useDispatch } from "react-redux";
import { useParams } from "react-router-dom";
import { mainUrl } from "../../api/api";
import { formatCurrency } from "../../api/format";
import { loadChannels } from "../../redux/action/target";
import Button from "../Button/Button";
import FilterLeadsReport from "../FilterForm/FilterLeadsReport";
import Header from "../Header/Header";
import Activity from "../ActivityDetail/Activity";
import { useQuery } from "react-query";
import LoadedComponent from "../Loaded/LoadedComponent";

// const ReportLeadDetail = () => {
//   const params = useParams();
//   const { user_type, user_id, detail_type, start, end } = params;
//   const {data, isLoading, error} = useQuery()
// }
const ReportLeadDetail = () => {
  const params = useParams();
  const { user_type, user_id, detail_type, start, end } = params;
  const [reportDataDeal, setReportDataDeal] = useState(null);
  const [reportDataHot, setReportDataHot] = useState(null);
  const dispatch = useDispatch();
  // filter
  const [filterCompany, setFilterCompany] = useState();
  const [activityDetail, setActivityDetail] = useState(false);
  const [customerActivity, setCustomerActivity] = useState(null);
  const [orderId, setOrderId] = useState(null);
  const [mount, setMount] = useState(1)
  useEffect(() => {
    const startDate = localStorage.getItem("date_leads_start")
    const companyId = localStorage.getItem("company_leads_filter");
    const endDate = localStorage.getItem("date_leads_end");
    if(startDate === undefined || startDate === null){
      localStorage.setItem("date_leads_start", params.start === "now" ? "" : params.start)
      if(endDate === undefined || endDate === null){
        localStorage.setItem("date_leads_end", params.end === "now" ? "" : params.end);
      }
    }

  },[params]);

  const handleClickDetail = async (activity) => {
    try {
      const res = await axios.get(
        `${mainUrl}/activities?filter[id]=${activity?.activity?.id ?? ""}`,
        {
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${localStorage.token}`,
          },
        }
      );
      setCustomerActivity(res?.data?.data[0]);
      // console.log(res.data);
    } catch (error) {
      console.error(error);
    }
    setActivityDetail(!activityDetail);
    setOrderId(activity.activity ? activity.activity.order_id : null);
    // console.log(activity.activity);
  };
 
  const [filterStartDate, setFilterStartDate] = useState(
    params.start !== "now" ? params.start : localStorage.getItem("date_leads_start") !== undefined && localStorage.getItem("date_leads_start") !== null ?localStorage.getItem("date_leads_start")  : ""
  );
  const [filterEndDate, setFilterEndDate] = useState(params.end !== "now" ? params.end : localStorage.getItem("date_leads_end") !== undefined && localStorage.getItem("date_leads_end") !== null ? localStorage.getItem("date_leads_end"): "");
  useEffect(() => {
    dispatch(loadChannels(filterCompany));

  }, [
    dispatch,
    filterCompany,
  ]);

  const exportReportDeal = async () => {
    axios
      .get(
        `${mainUrl}/dashboard/report-leads/closing-deals?start_date=${
          filterStartDate ? moment(filterStartDate).format("YYYY-MM-DD") : ""
        }&end_date=${
          filterEndDate ? moment(filterEndDate).format("YYYY-MM-DD") : ""
        }&company_id=${filterCompany ? filterCompany : ""}&${
          user_type === "bum"
            ? "supervisor_id=" + parseInt(user_id)
            : user_type === "channel"
            ? "channel_id=" + parseInt(user_id)
            : user_type === "sales"
            ? "sales_id=" + parseInt(user_id)
            : ""
        }&is_export=1`,
        {
          method: "GET",
          responseType: "blob", // important
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${localStorage.token}`,
          },
        }
      )
      .then((response) => {
        const url = window.URL.createObjectURL(new Blob([response.data]));
        const link = document.createElement("a");
        link.href = url;
        link.setAttribute(
          "download",
          `Report Brands detail.xlsx`
        );
        document.body.appendChild(link);
        link.click();
      })
      .catch((err) => {
        console.log();
      });
  };

  const exportReportHot = async () => {
    axios
      .get(
        `${mainUrl}/dashboard/report-leads/hot?start_date=${
          filterStartDate ? moment(filterStartDate).format("YYYY-MM-DD") : ""
        }&end_date=${
          filterEndDate ? moment(filterEndDate).format("YYYY-MM-DD") : ""
        }&company_id=${filterCompany ? filterCompany : ""}&${
          user_type === "bum"
            ? "supervisor_id=" + parseInt(user_id)
            : user_type === "channel"
            ? "channel_id=" + parseInt(user_id)
            : user_type === "sales"
            ? "sales_id=" + parseInt(user_id)
            : ""
        }&is_export=1`,
        {
          method: "GET",
          responseType: "blob", // important
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${localStorage.token}`,
          },
        }
      )
      .then((response) => {
        const url = window.URL.createObjectURL(new Blob([response.data]));
        const link = document.createElement("a");
        link.href = url;
        link.setAttribute("download", `ReportLeads Hot.xlsx`);
        document.body.appendChild(link);
        link.click();
      })
      .catch((err) => {
        console.log();
      });
  };
  // console.log(reportDataHot, "check data hot")
  // reportDataHot && reportDataHot.length !== 0
  //             ? user_type === "bum"
  //               ? reportDataHot[0].bum
  //               : user_type === "channel"
  //               ? reportDataHot[0].channel
  //               : user_type === "sales"
  //               ? reportDataHot[0].name
  //               : ""
  //             : ""
  

  const getDetailQuotation = async (params) => {
    console.log(params, "check params");
    const isTypeUser = await localStorage.getItem("user_type_leads_filter");
      const isChannels = await localStorage.getItem("channels_leads_filter");
      const checkChannels = isChannels === undefined || isChannels === null ? true : false
    const config = {
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${localStorage.token}`,
      },
    };
    const hotStartDate = params.detail_type === "hot" && params.filterStartDate !== undefined && params.filterStartDate !== null && params.filterStartDate !== "now" && params.filterStartDate !== "" ? params.filterStartDate : "2020-01-01";
    const hotEndDate = params.detail_type === "hot" && params.filterEndDate !== undefined && params.filterEndDate !== null && params.filterEndDate !== "now" && filterEndDate !== "" ? params.filterEndDate : moment(new Date()).format("YYYY-MM-DD");

    const dealStartDate = params.detail_type !== "hot" && params.filterStartDate !== undefined && params.filterStartDate !== null && params.filterStartDate !== "now" && params.filterStartDate !== "" ? params.filterStartDate : "";
    const dealEndDate = params.detail_type !== "hot" && params.filterEndDate !== undefined && params.filterEndDate !== null && params.filterEndDate !== "now" && filterEndDate !== "" ? params.filterEndDate : ""
    console.log(hotStartDate, hotEndDate, "<<< hot deal >>>", dealStartDate, dealEndDate);
      try { 
        
        const res = await axios.get(
        `${mainUrl}/dashboard/report-leads/detail-quotation?start_date=${
          params.detail_type === "hot" ? hotStartDate : dealStartDate
        }&end_date=${
          params.detail_type === "hot" ? hotEndDate : dealEndDate
        }&${
          isTypeUser === "sales"
          ?"sales_id=" + parseInt(params.user_id ?? "")
          : isTypeUser === "store"
            ? "channel_id=" + parseInt(params.user_id ?? "")
            : "supervisor_id=" + parseInt(params.user_id ?? "")
        }&type=${params?.detail_type === "hot" ? "quotation" : "deal"}&per_page=${params?.detail_type === 'hot' ? '100' : '100'}&page=${params.mount}`,
        config
      );
      if (params?.detail_type === "hot") {
          setReportDataHot(res?.data?.data);
        } else if (params?.detail_type === "deal") {
          setReportDataDeal(res?.data?.data);
        }
      return res.data
    } catch (error) {
      console.error(error)
    }
  }

  const {data: dataReport, isLoading, error} = useQuery(["detailQuotation",user_id, detail_type, filterStartDate, filterEndDate, mount], () => getDetailQuotation({user_id, detail_type, filterStartDate, filterEndDate, mount}));
  if(isLoading){
    return <LoadedComponent />
  }
  if(error){
    return (<h4>Terjadi kesalahan</h4>)
  }

  return (
    <div>
      <Header
        icon=""
        title={`Report Leads`}
        back={true}
        user={false}
      />
  
      <FilterLeadsReport
        company={false}
        channel={false}
        supervisor={false}
        download={detail_type === "hot" ? exportReportHot : exportReportDeal}
        setFilterStartDate={setFilterStartDate}
        setFilterEndDate={setFilterEndDate}
      />
      {detail_type === "hot" ? (
        <>
          <div style={{ overflow: "scroll" }}>
            <table className="" style={{ margin: "10px 0" }}>
              <thead>
                <tr>
                  <th>No.</th>
                  <th>Date</th>
                  <th>Name</th>
                  {/* <th>Sales</th> */}
                  <th>Channel</th>
                  <th>Quotation</th>
                  <th>Status</th> 
                  {/* <th>Estimated Value</th> */}
                  <th>Action</th>
                </tr>
              </thead>
              <tbody>
                {reportDataHot &&
                  reportDataHot.map((data, idx) => {
                    return (
                      <tr key={idx}>
                        <td>{dataReport.from + idx}</td>
                        <td>
                          {moment(data?.created_at).format(
                            "YYYY-MM-DD"
                          )}
                        </td>
                        <td>{data?.customer?.first_name ?? ""} {data?.customer?.last_name ?? ""}</td>
                        {/* <td>{data?.name}</td> */}
                        <td>{data?.channel?.name}</td>

                        <td>
                          {data.total_price && formatCurrency(data.total_price)}
                        </td>
                        <td>
                          {data.payment_status === "1" && "QUOTATION"}
                          {data.payment_status === "2" && "SHIPMENT"}
                          {data.payment_status === "5" && "CANCELLED"}
                          {data.payment_status === "6" && "RETURNED"}
                         
                        </td>
                        {/* <td>
                          {data.estimated_value &&
                            formatCurrency(data.estimated_value)}
                        </td> */}
                        <td>
                          <div
                            onClick={() => handleClickDetail(data)}
                            className="activity-detail-btn"
                          >
                            <img
                              src="/Asset/Action Icon/eye.png"
                              style={{ marginRight: "5px" }}
                              alt="eye"
                            />
                            See Detail
                          </div>
                        </td>
                      </tr>
                    );
                  })}
              </tbody>
            </table>
            <div >
            <div style={{display: dataReport?.prev_page_url === null ? "none" : "block"}}>
                <Button
                  onClick={(e) => setMount((prev) => prev-1)}
                  icon=""
                  title={"Prev"}
                  style={{ width: "11rem!important"}}
                  btnStyle={"primary-btn"}
                />
            </div>
              
            <div style={{display: dataReport?.next_page_url === null ? "none" : "block"}}>
               <Button
                onClick={(e) => {setMount((prev) => prev+1)}}
                icon=""
                title={"Next"}
                style={{ width: "11rem!important", display: dataReport?.next_page_url === null ? "none" : "block"}}
                btnStyle={"primary-btn"}
              />
            </div>
        </div>
          </div>
        </>
      ) : detail_type === "deal" ? (
        <>
          <table className="" style={{ margin: "10px 0" }}>
            <thead>
              <tr>
                <th>No.</th>
                <th>Date</th>
                <th>Name</th>
                <th>Sales</th>
                <th>Channel</th>
                <th>Invoice Number</th>
                <th>Invoice Price</th>
                <th>Amount Paid</th>
                <th>Action</th>
              </tr>
            </thead>
            <tbody>
              {reportDataDeal &&
                reportDataDeal.map((data, idx) => {
                 
                  return (
                    <tr key={idx}>
                      <td>{idx + 1}</td>
                      <td>
                        {moment(data?.created_at).format("YYYY-MM-DD")}
                      </td>
                      <td>{data?.customer?.first_name}</td>
                      <td>{data?.user?.name}</td>
                      <td>{data?.channel?.name}</td>
                      <td>{data?.invoice_number}</td>
                      <td>
                        {data?.total_price &&
                          formatCurrency(data.total_price)}
                      </td>
                      <td>
                        {data?.amount_paid && formatCurrency(data?.amount_paid)}
                      </td>
                      <td>
                        <div
                          onClick={() => handleClickDetail(data)}
                          className="activity-detail-btn"
                        >
                          <img
                            src="/Asset/Action Icon/eye.png"
                            style={{ marginRight: "5px" }}
                            alt="eye"
                          />
                          See Details
                        </div>
                      </td>
                    </tr>
                  );
                })}
            </tbody>
          </table>
          <div >
            <div style={{display: dataReport?.prev_page_url === null ? "none" : "block"}}>
                <Button
                  onClick={(e) => setMount((prev) => prev-1)}
                  icon=""
                  title={"Prev"}
                  style={{ width: "11rem!important"}}
                  btnStyle={"primary-btn"}
                />
            </div>
              
            <div style={{display: dataReport?.next_page_url === null ? "none" : "block"}}>
               <Button
                onClick={(e) => {setMount((prev) => prev+1)}}
                icon=""
                title={"Next"}
                style={{ width: "11rem!important", display: dataReport?.next_page_url === null ? "none" : "block"}}
                btnStyle={"primary-btn"}
              />
            </div>
        </div>
        </>
      ) : (
        ""
      )}
      {customerActivity ? (
        <Activity
          activityDetail={activityDetail}
          setActivityDetail={setActivityDetail}
          customerActivity={customerActivity}
          orderId={orderId}
        />
      ) : (
        ""
      )}
    </div>
  );
};

export default ReportLeadDetail;
