import axios from "axios";
import moment from "moment";
import React, { useEffect, useState } from "react";
import { useLocation } from "react-router-dom/cjs/react-router-dom.min";
import { Link } from "react-router-dom";
import { mainUrl, config as isConfig } from "../../api/api";
import { formatCurrency } from "../../api/format";
import Button from "../Button/Button";
import LoadedComponent from "../Loaded/LoadedComponent";
import Popup from "../Popup/Popup";
import DiscountPopup from "../Popup/Popup Component/DiscountPopup";
import CancelOrder from "../Popup/Popup Components/CancelOrder/CancelOrder";
import UpdateDiscounts from "../Popup/Popup Components/UpdateDiscounts/UpdateDiscounts";
import Invoice from "./Invoice";
import NewProduct from "./NewProduct";
import PaymentDetail from "./PaymentDetail";
import ProductListsOrder from "./ProductListsOrder";
import Quotation from "./Quotation";
import CurrencyInput from "react-currency-input-field";

const OrderDetail = (props) => {
  const location = useLocation();
  const { orderId, user } = props;
  const [orderData, setOrderData] = useState(null);
  const [loadOrder, setLoadOrder] = useState(false);

  const [updateDiscountsPopup, setUpdateDiscountPopup] = useState(false);
  const [updateDiscount, setUpdateDiscount] = useState(false);
  const [cancelPopup, setCancelPopup] = useState(false);

  const [allDiscount, setAllDiscount] = useState([]);

  const [discount_ids, setDiscount_ids] = useState([]);

  const [percentageForm, setPercentageForm] = useState(false);
  const [packing, setPacking] = useState(0);
  const [shipping, setShipping] = useState(null);
  const [addDiscount, setAddDiscount] = useState(null);
  // console.log(orderData, "check orderData")
  const handleUpdateDiscount = async (orderData) => {
    const data = {
      discount_ids: discount_ids.length !== 0 ? discount_ids : null,
      additional_discount: addDiscount
    }
    // console.log(addDiscount, discount_ids, "check discount", orderData)
    const result = await axios.put(`${mainUrl}/orders/${orderData.id}`, data, isConfig)
                        .then((res) => res)
                        .catch((error) => error.response);
    console.log(result, "checkimng sresul yah")







    // const updateOrder = async () => {
    //   try {
    //     const res = await axios.post(`${mainUrl}/orders/preview`, data, config);
    //     setTempOrder(res.data.data);
    //     setOrderIsVerified(true);
    //   } catch (error) {
    //     setOrderIsVerified(false);

    //     if (error.response) {
    //       setAlert(error.response.data.errors.lead_id[0]);
    //     }
    //   }
    // };
  }
  useEffect(() => {
    const config = {
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${localStorage.token}`,
      },
    };
  
    setLoadOrder(false);
    const getOrderData = async () => {
      try {
        const res = await axios.get(
          `${mainUrl}/orders/${orderId}`,
          config
        );
        
        setOrderData(res.data.data);
        setLoadOrder(true);
      } catch (error) {
        console.error(error);
        setLoadOrder(true);
      }
    };

    orderId && getOrderData();
  }, [orderId]);
  return orderData && loadOrder ? (
    <div>
      {orderData.cart_demand && (
        <NewProduct cart_demand={orderData.cart_demand} />
      )}

      <ProductListsOrder order_details={orderData.order_details} user={user} />

      <hr />
      <div>
        <div className="d-flex justify-content-between">
          <div>
            <p>Packing Fee:</p>
            <p>Shipping Fee:</p>
            <p>Discount:</p>
            <p>Discount Name:</p>
            <p>Sub total:</p>
            <p>Additional Discount:</p>
          </div>

          <div className="text-end">
            <p>
              {orderData.packing_fee
                ? formatCurrency(orderData.packing_fee)
                : formatCurrency(0)}
            </p>
            <p>
              {orderData.shipping_fee
                ? formatCurrency(orderData.shipping_fee)
                : formatCurrency(0)}
            </p>
            <p>{formatCurrency(orderData.total_discount)}</p>
            <p>{orderData.discount ? orderData.discount.name : "-"}</p>
            <p>
              {formatCurrency(
                orderData.original_price - orderData.total_discount
              )}
            </p>
            <p>
              {orderData.additional_discount
                ? formatCurrency(orderData.additional_discount)
                : formatCurrency(0)}
              (
              {orderData.additional_discount_ratio
                ? orderData.additional_discount_ratio
                : 0}
              %)
            </p>
          </div>
        </div>
        <hr />
        <div className="d-flex justify-content-between">
          <div>
            <p>Total Price:</p>
            <p>Expected Delivery Date:</p>
          </div>
          <div className="text-end">
            <p>{formatCurrency(orderData.total_price)}</p>
            <p>
              {moment(orderData.expected_shipping_datetime).format(
                "DD MMMM YYYY"
              )}
            </p>
          </div>
        </div>
        <hr />
        <div className="d-flex justify-content-between">
          <div>
            <p>Payment Status:</p>
            <p>Total Paid:</p>
            <p>Total Unpaid:</p>
          </div>
          <div className="text-end">
            <p>{orderData.payment_status}</p>
            <p>{formatCurrency(orderData.amount_paid)}</p>
            <p>
              {formatCurrency(orderData.total_price - orderData.amount_paid)}
            </p>
          </div>
        </div>
        <hr />
          <div className="mb-2">
            <div className="justify-content-between">
              <div className="d-flex justify-content-between">
                <div>
                  {user?.data?.as?.toUpperCase() === "DIRECTOR" && <p>Request by:</p>}
                  {user?.data?.as?.toUpperCase() === "DIRECTOR" && <p>Channel Name:</p>}
                  {user?.data?.as?.toUpperCase() === "DIRECTOR" && orderData.approval_note && <p>Approval Note By BUM:</p>}
                  {orderData?.approved_by && <p>{orderData?.approval_status === "APPROVED" ? "Approved" : "Rejected"} By:</p>}
                  <p>Payment Status:</p>
                </div>

                <div className="text-end">
                  {user?.data?.as?.toUpperCase() === "DIRECTOR" && <p>{orderData.user.name}</p>}
                  {user?.data?.as?.toUpperCase() === "DIRECTOR" && <p>{orderData.channel.name}</p>}
                  {user?.data?.as?.toUpperCase() === "DIRECTOR" && orderData.approval_note && <p>{orderData.approval_note}</p>}
                  {orderData?.approved_by && <p>{orderData.approved_by?.name}</p>}
                  <p>
                    {orderData.approval_status && orderData.approval_status?.split("_")?.join(" ")}
                  </p>
                </div>
              </div>
            </div>
          </div>
       
        {orderData.approval_status !== "REJECTED" && <PaymentDetail orderId={orderId ? orderId : ""} />}
        {orderData.payment_status === "SETTLEMENT" ? (
          <Invoice orderId={orderId ? orderId : ""} />
        ) : (
          <div>
            {orderData.approval_status !== "WAITING_APPROVAL" ? (
              orderData.approval_status === "REJECTED" ? (
                <div className="mt-2">
                  <div>
                    <Button
                      title={"Add Payment"}
                      btnStyle={"primary-btn"}
                      btnWidth={"100%"}
                      disabled={true}
                    />
                  </div>
                </div>
              ) : (
                <div className="mt-2">
                  <Link to={`/dashboard/payment/${orderId}`}>
                    <Button
                      title={"Add Payment"}
                      btnStyle={"primary-btn"}
                      btnWidth={"100%"}
                      disabled={false}
                    />
                  </Link>
                </div>
              )
            ) : (
              ""
            )}
            <Quotation orderId={orderId ? orderId : ""} />
          </div>
        )}

        {orderData.payment_status !== "NONE" ? (
          ""
        ) : user.data.type === "SALES" ? (
          <div className="d-flex justify-content-between">
            <div
              style={{ width: "48%" }}
              onClick={() => setUpdateDiscount(!updateDiscount)}
            >
              <Button
                title={"Edit Discounts"}
                btnStyle={"outline-btn"}
                btnWidth={"100%"}
                disabled={false}
              />
            </div>
            <div
              style={{ width: "48%" }}
              onClick={() => setCancelPopup(!cancelPopup)}
            >
              <Button
                title={"Cancel Order"}
                btnStyle={"btn-danger"}
                btnWidth={"100%"}
                disabled={false}
              />
            </div>
          </div>
        ) : (
          ""
        )}
        {updateDiscount && (
          <div
            className="mt-3 mb-3"
            style={{ padding: "15px", border: "1px solid #000" }}
          >
            <h3>Discount:</h3>

            <div
              className="p-2 d-flex justify-content-between"
              style={{
                border: "1px solid #000",
                marginBottom: "5px",
                borderRadius: "4px",
              }}
              onClick={() => setUpdateDiscountPopup(!updateDiscountsPopup)}
            >
              <div>
                <div className="d-flex align-items-center">
                  <img src="/Asset/Discount.svg" alt="discount" />
                  <h5 style={{ margin: "0 5px" }}>Discount</h5>
                </div>
              </div>
              <img src="/Asset/Arrow Icon/RightArrow.png" alt="rightarrow" />
            </div>
            <div
              className="pointer"
             
            >
              <div className="discount d-flex justify-content-between align-items-center">
                <div>
                  {allDiscount.length !== 0 ? (
                    allDiscount.map((discount, idx) => {
                      return (
                        <div
                          className="p-2"
                          style={{
                            border: "1px solid #000",
                            marginBottom: "5px",
                            borderRadius: "4px",
                          }}
                          key={idx}
                        >
                          <div className="d-flex align-items-center">
                            <img src="/Asset/Discount.svg" alt="discount" />
                            <h5 style={{ margin: "0 5px", fontSize:"13px" }}>
                              {discount ? discount.name : "Discount"}
                            </h5>
                          </div>

                          {discount && (
                            <div className="mt-2">
                              <p style={{fontSize:"11px"}}>{discount.description}</p>
                            </div>
                          )}
                        </div>
                      );
                    })
                  ) : (
                    <div>
                      <div className="d-flex align-items-center">
                        <img src="/Asset/Discount.svg" alt="discount" />
                        <h5 style={{ margin: "0 5px" }}>Discount</h5>
                      </div>
                    </div>
                  )}
                </div>
                
              </div>
            </div>
            <div className="mt-3">
              <label>Additional Discount</label>
              <div className="form-check">
                <label htmlFor="checkboxForPercentageForm">
                  Discount in Percent
                </label>
                <input
                  className="form-check-input"
                  type="checkbox"
                  value=""
                  id="checkboxForPercentageForm"
                />
              </div>
              {percentageForm ? (
                <input
                  type="text"
                  id="delivery"
                  name="delivery"
                  className="form-control"
                  placeholder="Input %"
                  onChange={(e) => setAddDiscount(e.target.value)}
                  style={{ height: "41px" }}
                />
              ) : (
                <input
                  type="text"
                  id="delivery"
                  name="delivery"
                  className="form-control"
                  placeholder="Input here"
                  onChange={(e) => setAddDiscount(e.target.value)}
                  style={{ height: "41px" }}
                />
              )}
            </div>
            <div className="mt-2" onClick={() => handleUpdateDiscount(orderData)}>
              <Button
                title={"Update Discount"}
                icon={""}
                btnWidth={"100%"}
                btnStyle="primary-btn"
              />
            </div>
          </div>
        )}
      </div>
      <Popup popup={cancelPopup} setPopup={setCancelPopup}>
        <CancelOrder orderId={orderId} setPopup={setCancelPopup} />
      </Popup>
      <Popup popup={updateDiscountsPopup} setPopup={setUpdateDiscountPopup}>
        <DiscountPopup
          setDiscount_ids={setDiscount_ids}
          discount_ids={discount_ids}
          setPopup={setUpdateDiscountPopup}
          setAllDiscount={setAllDiscount}
          allDiscount={allDiscount}
        />
      </Popup>
    </div>
  ) : orderData === undefined ? (
    ""
  ) : (
    <LoadedComponent />
  );
};

export default OrderDetail;
