import { mainUrl } from "../../../../api/api"
import Axios from "axios"
import { config } from "../../../../api/api";
import { useQuery } from "react-query";
import moment from "moment";

export const fetchReport = async ({searchState, userId, userName}) => {
   

    const reportDeals = await Axios.get(`${mainUrl}/new-reports/sub/deals?company_id=${searchState.companyId ?? ""}&channel_id=${searchState.channelId ?? ""}&user_id=${userId}&start_date=${searchState.start ?? ""}&end_date=${searchState.end ?? ""}&user_type=${searchState.userType ?? ""}`, config).then((res) => res.data).catch((error) => error)

    const reportActiveLeads = await Axios.get(`${mainUrl}/new-reports/sub/active-leads?company_id=${searchState.companyId ?? ""}&channel_id=${searchState.channelId ?? ""}&user_id=${userId}&start_date=${searchState.start ?? ""}&end_date=${searchState.end ?? ""}&user_type=${searchState.userType ?? ""}`, config).then((res) => res.data).catch((error) => error)

    const reportEstimations = await Axios.get(`${mainUrl}/new-reports/sub/estimations?company_id=${searchState.companyId ?? ""}&channel_id=${searchState.channelId ?? ""}&user_id=${userId}&start_date=${searchState.start ?? ""}&end_date=${searchState.end ?? ""}&user_type=${searchState.userType ?? ""}`, config).then((res) => res.data).catch((error) => error)

    const reportNewLeads = await Axios.get(`${mainUrl}/new-reports/sub/new-leads?company_id=${searchState.companyId ?? ""}&channel_id=${searchState.channelId ?? ""}&user_id=${userId}&start_date=${searchState.start ?? ""}&end_date=${searchState.end ?? ""}&user_type=${searchState.userType ?? ""}`, config).then((res) => res.data).catch((error) => error)

    const reportQuotations = await Axios.get(`${mainUrl}/new-reports/sub/quotations?company_id=${searchState.companyId ?? ""}&channel_id=${searchState.channelId ?? ""}&user_id=${userId}&start_date=${searchState.start ?? ""}&end_date=${searchState.end ?? ""}&user_type=${searchState.userType ?? ""}`, config).then((res) => res.data).catch((error) => error)

    const reportFollowUp = await Axios.get(`${mainUrl}/new-reports/sub/follow-up?company_id=${searchState.companyId ?? ""}&channel_id=${searchState.channelId ?? ""}&user_id=${userId}&start_date=${searchState.start ?? ""}&end_date=${searchState.end ?? ""}&user_type=${searchState.userType ?? ""}`, config).then((res) => res.data).catch((error) => error)

    const reportLeadStatus = await Axios.get(`${mainUrl}/new-reports/sub/lead-status?company_id=${searchState.companyId ?? ""}&channel_id=${searchState.channelId ?? ""}&user_id=${userId}&start_date=${searchState.start ?? ""}&end_date=${searchState.end ?? ""}&user_type=${searchState.userType ?? ""}`, config).then((res) => res.data).catch((error) => error)

    return {
        reportDeals,
        reportActiveLeads,
        reportEstimations,
        reportNewLeads,
        reportQuotations,
        reportFollowUp,
        reportLeadStatus,
        id:userId,
        name: userName
    }
   
}
// searchState
export const useReportDeals = ({user, searchState}) => {


    return useQuery([`reportDeals${user.id}`, {searchState}], () => {
        return Axios.get(`${mainUrl}/new-reports/sub/deals?company_id=${searchState.companyId ?? ""}&channel_id=${searchState.channelId ?? ""}&user_id=${user.id}&start_date=${searchState.start ?? ""}&end_date=${searchState.end ?? ""}&user_type=${searchState.userType === "store" ? "store" : ""}`, config)
        .then((data) => {
            return data.data
            }).catch((error) => error)
    }, {refetchOnWindowFocus: (query) => query.state.status !== "error", staleTime: Infinity})
    
   
}

