import { mainUrl } from "../../../../api/api";
import Axios from 'axios';
const config = {
    headers: {
      "Content-Type": "application/json",
      Authorization: `Bearer ${localStorage.token}`,
    },
};
const checkStatus = (res) => {
    let response = {}
    if(res.status !== 200){
        response = {message: "Terjadi Kesalahan Saat Mengambil Data", success: false, status:res.status}
    }
    if(res.status === 200){
        response = {message: "Sukses Mengambil Data", success: true, data:res?.data, status:res.status}
    }
    return response
}
export const getAllDataProducts = async (id = "", product_id = "", colour_id = "", name = "") => {
    let response = {}
    try{
        const res = await Axios.get(`${mainUrl}/product-units?filter[id]=${id}&filter[product_id]=${product_id}&filter[colour_id]=${colour_id}&filter[name]=${name}`, config);
        if(res.status !== 200){
            response = {message: "Terjadi Kesalahan Saat Mengambil Data", success: false, status:res.status}
        }
        if(res.status === 200){
            response = {message: "Sukses Mengambil Data", success: true, data:res.data, status:res.status}
        }
    }catch(error){
        response ={message: error.response, success: false}
    }
    return response
}

export const getLocationsData = async (sku) => {
    let response = {}
    try{
        const res = await Axios.get(`${mainUrl}/locations?sku=${sku}`, config);

        if(res.status !== 200){
            response = {message: "Terjadi Kesalahan Saat Mengambil Data", success: false, status:res.status}
        }
        if(res.status === 200){
            response = {message: "Sukses Mengambil Data", success: true, data:res.data, status:res.status}
        }
    }catch(error){
        response = {message: error.response, success:false}
    }
    return response
}

export const addCart = async (item) => {
    console.log(item, 'check item cart')
    let response = {}
    try{
        const res = await Axios.put(`${mainUrl}/carts`, config, item);
        response = checkStatus(res)
    }catch(error){
        response = {message: error.response, success: false}
    }
    return response
}

