import React, { Fragment } from "react";
import Button from "../../../../components/Button/Button";
import { connect } from "react-redux";
const FiltersReport = ({prosesData: {dataFilterDate},
    searchState,
    setSearchState,
    channels,
    user,
    isTypeUser
}) => {
  
  const handleChangeDate = (e) => {
        setSearchState((prev) => {
            return {
                ...prev,
                [e.target.name]:e.target.value
            }
        })
  }
  const handleChangeCompany = (e) => {
    setSearchState((prev) => {
        return {
            ...prev,
            companyId: e.target.value
        }
    })
  }
  return (
    <div className="filter-form d-flex justify-content-between header-filter-responsive" style={{display: "grid"}}>
      <div className="header d-flex align-items-center">
        <img
          src="/Asset/Icon/Report.png"
          alt="report"
          style={{ width: "24px", height: "24px" }}
        />
        <h3>Report</h3>
      </div>
      <div className="report-filter-form report-header-filter" style={{gridTemplateColumns:"repeat(4,1fr)", gap: "20px" }}>
        <select
          className="form-select"
          name="companys"
          value={searchState.idCompany}
          onChange={handleChangeCompany}
          style={{display: isTypeUser.toUpperCase() !== "DIRECTOR" ? "none" : "block"}}
        >
          {user.data.type !== "DIRECTOR" ? (
            user.data.company_id ? (
              <option value={1}>Melandas</option>
            ) : (
              <option value={2}>Dio Living</option>
            )
          ) : (
            <Fragment>
              <option value={1}>Melandas</option>{" "}
              <option value={2}>Dio Living</option>
            </Fragment>
          )}
        </select>
        <select
          className="form-select"
          name="channels"
          value={searchState.idChannel}
          onChange={(e) => {
            setSearchState((prev) => {
                return {
                    ...prev,
                    channelId:e.target.value
                }
            })
          }}
          style={{display: isTypeUser.toUpperCase() === "DIRECTOR" ? "none" : "block"}}
        >
          <option value="">Select Channel</option>
          {channels.data.map((channel) => {
            return (
              <option value={channel.id} key={channel.id}>
                {channel.name}
              </option>
            );
          })}
        </select>
        {/* <select
          className="form-select"
          name="users"
          onChange={(e) => setFilterUser(e.target.value)}
        >
          <option value="">Select User</option>
          {usersList.data.map((user) => {
            return (
              <option value={user.id} key={user.id}>
                {user.name}
              </option>
            );
          })}
        </select> */}
        
        <div style={{display: "flex", alignItems: "center"}}>
          <input
            type="date"
            id="start"
            name="start"
            value={searchState.start}
            className="form-control"
            placeholder="Start Month"
            onChange={handleChangeDate}
          />
          <div className="input-group-addon"style={{margin: "0 10px"}}>to</div>
          <input
            type="date"
            id="end"
            name="end"
            value={searchState.end}
            className="form-control"
            placeholder="End Month"
            onChange={handleChangeDate}
            style={{margin:"0"}}
          />
        </div>
        <Button onClick={() => {
          setSearchState((prev) => ({
            ...prev,
            onTouch:true
          }))
        }}icon="" title="Filter" style={{width:"11rem!important"}} btnStyle={"primary-btn"} />
      </div>
    </div>
  );
};
const mapStateToProps = (state) => ({

  prosesData: state.prosesData
});
export default connect(mapStateToProps)(FiltersReport);
