
import React, { useState } from "react";
import { Link } from "react-router-dom";
import { useParams, useHistory } from "react-router-dom";
// import { isValidate } from "../../../lib/Validate";
import LoadingTableAllData from "../../Loaded/LoadingTableAllData";
import Header from "./ReportLeadsHead";
// import Button from "../../Button/Button";
import useReportLeadDropList from "../apiReportLeads/useReportLeadDropList";
import ReportLeadsHeader from "./ReportLeadsHeader";
import { connect } from "react-redux";
const ReportLeadsDrop = ({ReportLeadFilterRedux: {channelId, companyId, brandId, currentChannel, startEndDate, userType}}) => {
    const params = useParams();
    const history = useHistory();
    const historyState = history?.location?.state
    const { user_id, detail_type } = params;
    const [searchState, setSearchState] = useState({
        start: startEndDate.start,
        end: startEndDate.end,
        channelId: channelId === null ? "" : channelId,
        companyId: companyId === null ? "" : companyId,
        brandId: brandId === null ? "" : brandId,
        userType: userType, 
        currentUserType: "",
        userId: user_id,
        status: detail_type,
        count: 1
    });
   
    const { data:reportDataDrop, error, isLoading } = useReportLeadDropList({searchState});

    console.log(reportDataDrop, "check report hot")
   
  if(isLoading){
    return <div className="">
            <Header
              icon=""
              title={`Report Leads - DROP`}
              back={true}
              user={false}
            />
            <ReportLeadsHeader 
                searchState={searchState}
                setSearchState={setSearchState}
                type="company"
                channel={false}
                company={false}
            />
            <LoadingTableAllData />        
          </div>
  }

  if(error){
    return <h4>Terjadi kesalahan pada server</h4>
  }

  return (
    <div>
      <Header
        icon=""
        title={`Report Leads - DROP`}
        back={true}
        user={false}
      />

        <ReportLeadsHeader 
            searchState={searchState}
            setSearchState={setSearchState}
            user={historyState?.user ?? null}
            channel={false}
            company={false}
            type="type"
        />
      <div style={{ overflow: "scroll" }}>
          <table className="" style={{ margin: "10px 0" }}>
            <thead>
              <tr>
                <th>No.</th>
                <th>Sales</th>
                <th>Customer</th>
                <th>Channel</th>
                <th>Action</th>
              </tr>
            </thead>
            <tbody>
              {reportDataDrop &&
                reportDataDrop?.map((data, idx) => {
                  return (
                    <tr key={idx}>
                      <td>{idx + 1}</td>
                      <td>{data.sales ? data.sales.name : ""}</td>
                      <td>
                        {data.customer.first_name} {data.customer.last_name}
                      </td>
                      <td>{data.channel.name}</td>
                      <td>
                        <Link
                          to={`/dashboard/customers/customer_detail/${data.id}/${data.customer_id}`}
                        >
                          Lead Detail
                        </Link>
                      </td>
                    </tr>
                  );
                })}
            </tbody>
          </table>
        </div>
    </div>
  );
};
const mapStateToProps = (state) => ({
    auth: state.auth,
    target: state.target,
    prosesData: state.prosesData,
    ReportLeadFilterRedux: state.ReportLeadFilterRedux,
  });
export default connect(mapStateToProps)(ReportLeadsDrop);
