export const login = (body) => async (dispatch) => {
  try {
    const res = await axios.post(`${mainUrl}/auth/token`, body, {
      headers: { "Content-Type": "application/json" },
    });

    const api = res.data;

    if (api?.data) {
      dispatch({ type: LOGIN_SUCCESS, payload: api.data });
      dispatch(loadUser());
      return { status: "success" };
    }

    if (api?.message) {
      return {
        status: "otp",
        email: body.email,          
        message: api.message,      
      };
    }

    // fallback
    return { status: "error", error: new Error("Unexpected response") };
  } catch (error) {
    dispatch({ type: LOGIN_FAIL });
    return { status: "error", error };
  }
};

//Logout
export const logout = () => (dispatch) => {
  dispatch({
    type: LOGOUT,
  });
};
