import React, { useEffect, useState } from "react";
import Header from "../../../components/Header/Header";
import { getAllDataProducts } from "./apiProduct";
import { useHistory } from "react-router-dom";
import { formatCurrency } from "../../../api/format";
const SelectChannel = () => {
  const [stocks, setStocks] = useState(null);
  const [filterChannel, setFilterChannel] = useState("");
  const [isLoading, setIsLoading] = useState(true);
  const [dataSearch, setDataSearch] = useState(null);
  const history = useHistory()
  useEffect(() => {
    const config = {
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${localStorage.token}`,
      },
    };
     const fetchingData = async () => {
      const res = await getAllDataProducts();
      const { data, status } = res
      if(status === 200){
        setStocks(data.data)
        setIsLoading(false)
      }
    }
    fetchingData()
  }, [filterChannel]);
  useEffect(() => {
    const filterDataSearch = () => {
      let newRes = stocks.filter((datas,i) => {
        const byName = datas?.name?.toUpperCase().indexOf(filterChannel.toUpperCase());
        const bySku = datas?.sku?.toUpperCase().indexOf(filterChannel.toUpperCase());
          if(byName >= 0 || bySku >= 0){
              return datas
          }
      })
      setDataSearch(newRes)
  }
  !isLoading && filterDataSearch()
  }, [stocks, isLoading, filterChannel]);
  const handleDirectPage = (data) => {
    history.push({
      pathname: `/dashboard/product/stock/channel/${data.sku}`,
      state:{
        id: data.id,
        data
      }
    })
  }
  return (
    <div className="stock" id="stock">
      <Header title="Select Product Unit" back={true} icon="" />
      <div className="d-flex align-items-center">
        <input
          type="text"
          className="form-control"
          name="companys"
          style={{ height: "41px", width: "40%" }}
          placeholder="Search by product name or sku"
          value={filterChannel}
          onChange={(e) => setFilterChannel(e.target.value)}
        />
      </div>
      <div className="mt-4">
        <table className="data" style={{ margin: "10px 0" }}>
          <thead>
            <tr>
              <th>SKU</th>
              <th>Nama Product</th>
              <th>Harga Product</th>
            </tr>
          </thead>
          <tbody>
            {stocks && dataSearch &&
              dataSearch.map((stock, idx) => {
                return (
                  <tr key={idx} style={{cursor:"pointer"}} onClick={() => handleDirectPage(stock)}>
                    <td>{stock.sku}</td>
                    <td>{stock.name}</td>
                    <td>{formatCurrency(stock.price)}</td>
                  </tr>
                );
              })}
          </tbody>
        </table>
      </div>
    </div>
  );
};

export default SelectChannel;
