import React, { useEffect, useRef, useState } from "react";
import axios from "axios";
import { useDispatch } from "react-redux";
import { useHistory, useLocation } from "react-router-dom";
import { LOGIN_SUCCESS } from "../../redux/action/types"; // adjust path
import { loadUser } from "../../redux/action/auth"; // adjust path
import { mainUrl } from "../../api/api";

const pad = (n) => (n < 10 ? `0${n}` : n);

export default function OTPScreen() {
  const dispatch = useDispatch();
  const history = useHistory();
  const { state } = useLocation();
  const email = state?.email;

  useEffect(() => {
    if (!email) history.replace("/login");
  }, [email, history]);

  const [digits, setDigits] = useState(["", "", "", "", "", ""]);
  const inputsRef = useRef([]);
  const [secondsLeft, setSecondsLeft] = useState(300); // 5 minutes
  const [submitting, setSubmitting] = useState(false);
  const [errorMsg, setErrorMsg] = useState("");

  // countdown
  useEffect(() => {
    if (secondsLeft <= 0) return;
    const id = setInterval(() => setSecondsLeft((s) => s - 1), 1000);
    return () => clearInterval(id);
  }, [secondsLeft]);

  // when expired -> bounce back to login
  useEffect(() => {
    if (secondsLeft === 0) {
      setErrorMsg("OTP expired. Redirecting to login…");
      const t = setTimeout(() => history.replace("/login"), 1500);
      return () => clearTimeout(t);
    }
  }, [secondsLeft, history]);

  const onChangeDigit = (idx, val) => {
    if (!/^\d?$/.test(val)) return; // only 0-9, max one char
    const next = [...digits];
    next[idx] = val;
    setDigits(next);
    if (val && idx < 5) inputsRef.current[idx + 1]?.focus();
  };

  const onKeyDown = (idx, e) => {
    if (e.key === "Backspace" && !digits[idx] && idx > 0) {
      const next = [...digits];
      next[idx - 1] = "";
      setDigits(next);
      inputsRef.current[idx - 1]?.focus();
      e.preventDefault();
    }
    if (e.key === "ArrowLeft" && idx > 0) inputsRef.current[idx - 1]?.focus();
    if (e.key === "ArrowRight" && idx < 5) inputsRef.current[idx + 1]?.focus();
  };

  const onPaste = (e) => {
    const text = e.clipboardData.getData("text").trim();
    if (!/^\d{6}$/.test(text)) return;
    setDigits(text.split(""));
    inputsRef.current[5]?.focus();
    e.preventDefault();
  };

  const code = digits.join("");
  const disabled = code.length !== 6 || secondsLeft === 0 || submitting;

  const buildVerifyPayload = ({ email, code }) => {
    const p = new URLSearchParams();
    p.append("otp", code);
    p.append("email", email);
    p.append("device_id", "website");
    p.append("device_name", "website");
    p.append("lat", "");
    p.append("lng", "");
    return p.toString();
  };

  const handleVerify = async (e) => {
    e.preventDefault();
    if (disabled) return;
    setSubmitting(true);
    setErrorMsg("");

    try {
      const payload = buildVerifyPayload({ email, code });
      const res = await axios.post(`${mainUrl}/auth/verify-otp`, payload, {
        headers: { "Content-Type": "application/x-www-form-urlencoded" },
      });
      console.log(res, "ori");
      console.log(res.data.data, "ori dat dal dat");
      if (res?.data?.data) {
        dispatch({ type: LOGIN_SUCCESS, payload: res.data.data.token });
        dispatch(loadUser());
        history.replace("/dashboard");
      } else {
        setErrorMsg(res?.data?.message || "Verification failed");
        setSubmitting(false);
      }
    } catch (err) {
      setErrorMsg(
        err?.response?.data?.message || "Invalid code. Please try again."
      );
      setSubmitting(false);
    }
  };

  const handleResend = async () => {
    if (secondsLeft > 0) return;
    setErrorMsg("");
    try {
      // ⬇️ adjust to your resend endpoint
      await axios.post(`${mainUrl}/auth/resend-otp`, { email });
      setSecondsLeft(300);
      setDigits(["", "", "", "", "", ""]);
      inputsRef.current[0]?.focus();
    } catch (err) {
      setErrorMsg("Failed to resend OTP. Try again.");
    }
  };

  const minutes = Math.floor(secondsLeft / 60);
  const seconds = secondsLeft % 60;

  return (
    <section className="otp-wrapper" style={styles.wrapper}>
      <div style={styles.card}>
        <h2 style={{ marginBottom: 8 }}>Verify your email</h2>
        <p style={{ marginTop: 0, color: "#555" }}>
          We sent a 6-digit code to <strong>{email}</strong>
        </p>

        <form onSubmit={handleVerify} style={{ marginTop: 16 }}>
          <div style={styles.inputs} onPaste={onPaste}>
            {digits.map((d, i) => (
              <input
                key={i}
                ref={(el) => (inputsRef.current[i] = el)}
                value={d}
                onChange={(e) => onChangeDigit(i, e.target.value)}
                onKeyDown={(e) => onKeyDown(i, e)}
                inputMode="numeric"
                pattern="\d*"
                maxLength={1}
                autoComplete="one-time-code"
                style={styles.input}
              />
            ))}
          </div>

          <button
            type="submit"
            disabled={disabled}
            style={{ ...styles.button, opacity: disabled ? 0.6 : 1 }}
          >
            {submitting ? "Verifying…" : "Verify"}
          </button>
        </form>

        <div style={{ marginTop: 12, color: "#666", fontSize: 14 }}>
          Expires in {pad(minutes)}:{pad(seconds)}
        </div>

        {errorMsg && (
          <div style={{ marginTop: 10, color: "#c0392b", fontSize: 14 }}>
            {errorMsg}
          </div>
        )}

        {/* <div style={{ marginTop: 16, fontSize: 14 }}>
          Didn’t get the code?{" "}
          <button
            onClick={handleResend}
            disabled={secondsLeft > 0}
            style={{
              ...styles.linkBtn,
              opacity: secondsLeft > 0 ? 0.6 : 1,
            }}
          >
            Resend OTP
          </button>
        </div> */}

        <button
          onClick={() => history.replace("/login")}
          style={styles.linkBtn}
        >
          Back to login
        </button>
      </div>
    </section>
  );
}

// replace the `styles` in your Otp.jsx with this
const styles = {
  wrapper: {
    minHeight: "100vh",
    display: "grid",
    placeItems: "center",
    background: "#f7f9fb",
    padding: 16,
  },
  card: {
    background: "#fff",
    borderRadius: 16,
    padding: 28,
    width: "100%",
    maxWidth: 520,
    boxShadow: "0 2px 6px rgba(0,0,0,0.06), 0 16px 32px rgba(0,0,0,0.06)",
    textAlign: "center",
  },

  /* --- OTP input row --- */
  inputs: {
    display: "flex",
    justifyContent: "center",
    gap: 12,
    margin: "14px 0 18px",
    flexWrap: "wrap",
  },
  input: {
    width: 52, // <- fixed width
    height: 56,
    fontSize: 24,
    textAlign: "center",
    borderRadius: 12,
    border: "1px solid #e5e9f0",
    outline: "none",
    transition: "box-shadow .15s, border-color .15s",
  },

  button: {
    width: "100%",
    height: 48,
    background: "#2c8a90",
    color: "#fff",
    border: "none",
    borderRadius: 10,
    cursor: "pointer",
    fontWeight: 700,
    letterSpacing: 0.2,
  },
  linkBtn: {
    background: "transparent",
    border: "none",
    color: "#2c8a90",
    cursor: "pointer",
    padding: 0,
    marginTop: 8,
    textDecoration: "underline",
    fontSize: 14,
  },
};
