import React from "react";
import { connect } from "react-redux";
import { Link } from "react-router-dom";
import Header from "../../../components/Header/Header";
import "./Promo.scss";
import parse from "html-react-parser";

const PromoCategories = ({ promo: { promoCategories } }) => {
 
  
  return (
    promoCategories && (
      <div className="promo" id="promo">
        <Header title="Promo Categories" back={false} />

        <div className="row">
          {promoCategories?.data?.map((category) => {
            return (
              <div className="col-md-4" key={category.id}>
                <Link
                  to={`/dashboard/promo-categories/${category?.id ?? 0}/${category?.name?.replace(/[^\w\s]/g, "")?.split(" ")?.join("-") ?? ""}`}
                  style={{ textDecoration: "none", color: "#313132" }}
                >
                  <div className="card">
                    <img
                      src={category?.image[0]?.url}
                      alt=""
                      className="card-image"
                    />
                  </div>
                  <h4 className="mt-2">{category?.name}</h4>
                  <p>{parse(category?.description)}</p>
                </Link>
              </div>
            );
          })}
        </div>
      </div>
    )
  );
};

const mapStateToProps = (state) => ({
  promo: state.promo,
});

export default connect(mapStateToProps)(PromoCategories);
