import { useEffect, useRef, useState } from "react";
import { connect, useDispatch, useSelector } from "react-redux";
import { login } from "../../redux/action/auth";
import { loadTarget } from "../../redux/action/target";
import "./Login.css";
import { useHistory } from "react-router-dom/cjs/react-router-dom";

const LoginV2 = ({ auth: { failedLogin } }) => {
  const [inputValue, setInputValue] = useState({
    email: "",
    password: "",
  });
  const dispatch = useDispatch();
  const history = useHistory();
  const isAuthenticated = useSelector((state) => state.auth.isAuthenticated);
  useEffect(() => {
    isAuthenticated && window.location.assign("/dashboard");
  }, [isAuthenticated]);
  const emailRef = useRef();
  const passRef = useRef();

  // const handleSubmit = async (e) => {
  //   e.preventDefault();
  //   const data = {
  //     email: inputValue.email,
  //     password: inputValue.password,
  //   };
  //   dispatch(login(data));
  //   dispatch(loadTarget());
  // };

  const handleSubmit = async (e) => {
    e.preventDefault();
    const data = { email: inputValue.email, password: inputValue.password };

    const result = await dispatch(login(data)); // ⬅️ await the thunk result

    if (result?.status === "success") {
      // now safe to load other data
      dispatch(loadTarget());
    } else if (result?.status === "otp") {
      // go to OTP screen and pass the email
      history.push({
        pathname: "/otp",
        state: { email: result.email, from: "login" },
      });
    } else {
      // optional: show toast / leave the failedLogin alert
    }
  };
  return (
    <section className="gradient-form" style={{ backgroundColor: "#fff" }}>
      <div className="">
        <div className="row g-0" style={{ height: "100vh" }}>
          <div className="col-lg-7 d-flex align-items-center gradient-custom-2 justify-content-center">
            <div
              className="text-white px-3 py-4 p-md-1 mx-md-4"
              style={{ width: "70%" }}
            >
              <img
                src="/Asset/Auth Images/login image 3.png"
                alt="img bg"
                style={{ width: "100%" }}
              />
            </div>
          </div>
          <div
            className="col-lg-5 login-form d-flex justify-content-center align-items-center"
            style={{
              background: `url('/Asset/Auth Images/background auth.png'), linear-gradient(#17949d, #21b8c3)`,
              backgroundRepeat: "no-repeat",
              backgroundSize: "cover",
            }}
          >
            <div className="card-body p-md-5 mx-md-4 ">
              <div>
                <div className="text-center">
                  <img
                    src="/Asset/Auth Images/MovesLogo.png"
                    alt="logo"
                    className="mt-1 mb-5 pb-1"
                    style={{ width: "300px" }}
                  />
                </div>

                {/* <form onSubmit={localStorage.setItem("token","GluYMZYK670yIg3uKFeldZY67Z7dKhEOhaTjE2Gc")}> */}
                <form onSubmit={handleSubmit}>
                  <p>Please login to your account</p>
                  {failedLogin && (
                    <div
                      className="alert alert-danger"
                      role="alert"
                      style={{ textAlign: "center" }}
                    >
                      Your email or password is incorrect. <br />
                      Please try again.
                    </div>
                  )}
                  <div className="form-outline mb-4">
                    <input
                      onChange={(e) =>
                        setInputValue((prev) => ({
                          ...prev,
                          email: e.target.value,
                        }))
                      }
                      type="email"
                      id="email"
                      className="form-control"
                      name="email"
                      placeholder="Enter your email"
                      ref={emailRef}
                    />
                  </div>

                  <div className="form-outline mb-4">
                    <input
                      onChange={(e) =>
                        setInputValue((prev) => ({
                          ...prev,
                          password: e.target.value,
                        }))
                      }
                      type="password"
                      id="password"
                      name="password"
                      className="form-control"
                      placeholder="Enter your password"
                      ref={passRef}
                    />
                  </div>

                  <div className="text-center pt-1 mb-5 pb-1">
                    <button
                      className="btn btn-primary btn-block fa-lg gradient-custom-2 mb-3 form-control"
                      type="submit"
                      style={{ backgroundColor: "#006870" }}
                    >
                      Log in
                    </button>
                  </div>
                </form>
              </div>
            </div>
          </div>
        </div>
      </div>
    </section>
  );
};

const mapStateToProps = (state) => ({
  auth: state.auth,
});

export default connect(mapStateToProps)(LoginV2);
