import React, { useEffect, useState } from "react";
import { connect } from "react-redux";
import ProductListsOrder from "../../../components/ActivityDetail/ProductListsOrder";
import "./ApprovalDetail.scss";
import Button from "../../../components/Button/Button";
import { formatCurrency } from "../../../api/format";
import moment from "moment";
import axios from "axios";
import { mainUrl } from "../../../api/api";
import Popup from "../../../components/Popup/Popup";
import EditDiscount from "../../../components/Popup/Popup Components/EditDiscount/EditDiscount";
import PaymentDetail from "../../../components/ActivityDetail/PaymentDetail";
import { Link } from "react-router-dom";

const ApprovalDetail = ({
  auth: { user },
  data,
  activityDetail,
  setActivityDetail,
  refresh,
  setRefresh,
}) => {
  const [isLoading, setIsLoading] = useState(false);

  const [noteReject, setNoteReject] = useState("");
  const [additionalDiscount, setAdditionalDiscount] = useState(null);

  const [editDiscountPopup, setEditDiscountPopup] = useState(false);
  const [onReject, setOnReject] = useState(false);

  let priceDiscount =
    additionalDiscount === null ? data.additionalDiscount : additionalDiscount;

  function totalHpp(order_details) {
    let result = 0;
    for (let i = 0; i < order_details.length; i++) {
      result += order_details[i].product_unit.production_cost;
    }
    return result;
  }
  const onApprove = async () => {
    setIsLoading(true);
    try {
      const res = await axios.put(
        `${mainUrl}/orders/approve/${data.id}`,
        {},
        {
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${localStorage.token}`,
          },
        }
      );
      setIsLoading(false);
      setRefresh(!refresh);
      setActivityDetail(!activityDetail);
    } catch (error) {
      console.error(error);
      setIsLoading(false);
    }
  };

  const sendRejection = async () => {
    setIsLoading(true);
    if (noteReject.length > 5) {
      try {
        const res = await axios.put(
          `${mainUrl}/orders/approve/${data.id}`,
          {
            comment: noteReject,
            reject: true,
          },
          {
            headers: {
              "Content-Type": "application/json",
              Authorization: `Bearer ${localStorage.token}`,
            },
          }
        );
        setIsLoading(false);
        setRefresh(!refresh);
        setActivityDetail(!activityDetail);
      } catch (error) {
        setIsLoading(false);
      }
    }
  };
  const [preview, setPreview] = useState(0);
  const updatePreview = async () => {
    try {
      const res = await axios.post(
        `${mainUrl}/orders/preview-update/${data.id}`,
        {
          additional_discount: priceDiscount,
          discount_take_over_by: user.data.id,
        },
        {
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${localStorage.token}`,
          },
        }
      );
      setPreview(res.data.data.total_price);
    } catch (error) {
      console.error(error);
    }
  };

  useEffect(() => {
    updatePreview();
  }, [additionalDiscount]);
  
  return !data ? (
    ""
  ) : (
    <div
      className={`approval-detail ${activityDetail ? "activity-active" : ""}`}
    >
      <div className="header d-flex justify-content-between align-items-center">
        <h1>Detail Order</h1>
        <img
          src="/Asset/Times.png"
          alt="close"
          onClick={() => setActivityDetail(!activityDetail)}
        />
      </div>
      <ProductListsOrder
        order_details={data && data.order_details}
        user={user}
      />
      <div>
        <div className="d-flex justify-content-between">
          <div className="text-start">
            <p>Total Hpp:</p>
            <p>Packing Fee:</p>
            <p>Shipping Fee:</p>
            <p>Discount:</p>
            <p>Sub total:</p>
            <p>Discount Request:</p>
          </div>
          <div className="text-end">
            <p>{formatCurrency(totalHpp(data.order_details))}</p>
            <p>{formatCurrency(data.packing_fee)}</p>
            <p>{formatCurrency(data.shipping_fee)}</p>
            <p>{formatCurrency(data.total_discount)}</p>
            <p>{formatCurrency(data.original_price)}</p>
            <p>{`${formatCurrency(data.additional_discount)} (${
              data.additional_discount_ratio
            }%)`}</p>
          </div>
        </div>
        <hr />
        <div className="d-flex justify-content-between">
          <div className="text-start">
            <p>Total Price:</p>
            <p>Expeted Delivery Date:</p>
          </div>
          <div className="text-end">
            <p>{formatCurrency(data.total_price)}</p>
            <p>
              {moment(data.expected_shipping_datetime).format("DD MMMM YYYY")}
            </p>
          </div>
        </div>
        <hr />
        <div className="d-flex justify-content-between">
          <div className="text-start">
            <p>Request by:</p>
            <p>Channel Name:</p>
            <p>Approval Note by BUM</p>
          </div>
          <div className="text-end">
            <p>{data.discount_take_over_by.name}</p>
            <p>{data.discount_take_over_by.channel}</p>
          </div>
        </div>
        <div
          style={{
            border: "1px solid #eaeaea",
            padding: "10px",
            margin: "5px 0",
          }}
        >
          <p style={{ marginBottom: "0" }}>
            {data.approval_note ? data.approval_note : "-"}
          </p>
        </div>
        <div className="d-flex justify-content-between">
          <div className="text-start">
            <p>Status:</p>
          </div>
          <div className="text-end">
            <p>{data.approval_status}</p>
          </div>
        </div>

        <PaymentDetail orderId={data.id} />

        {data.approval_status !== "WAITING_APPROVAL" ? (
          data.approval_status === "REJECTED" ? (
            <div className="mt-2">
              <div>
                <Button
                  title={"Add Payment"}
                  btnStyle={"primary-btn"}
                  btnWidth={"100%"}
                  disabled={true}
                />
              </div>
            </div>
          ) : (
            <div className="mt-2">
              <Link to={`/dashboard/payment/${data.order_details[0].id}`}>
                <Button
                  title={"Add Payment"}
                  btnStyle={"primary-btn"}
                  btnWidth={"100%"}
                  disabled={false}
                />
              </Link>
            </div>
          )
        ) : (
          ""
        )}

        <div className="d-flex justify-content-between mt-2">
          <div onClick={() => setOnReject(!onReject)} style={{ width: "48%" }}>
            <Button
              title={"Reject"}
              btnStyle={"btn-danger"}
              btnWidth={"100%"}
              disabled={
                user.data.type === "DIRECTOR" &&
                user.data.app_approval_discount === false
                  ? true
                  : false
              }
            />
          </div>
          {user?.data?.as?.toUpperCase() !== "DIRECTOR" && data.additional_discount_ratio > data.discount_approval_limit_percentage ? (
            <div
              onClick={() => setEditDiscountPopup(!editDiscountPopup)}
              style={{ width: "48%" }}
            >
              <Button
                title={"Edit"}
                btnStyle={"outline-btn"}
                btnWidth={"100%"}
                disabled={
                  user.data.type === "DIRECTOR" &&
                  user.data.app_approve_discount === false
                    ? true
                    : false
                }
              />
            </div>
          ) : (
            <div onClick={() => onApprove()} style={{ width: "48%" }}>
              <Button
                title={"Approve"}
                btnStyle={"outline-btn"}
                btnWidth={"100%"}
                disabled={
                  user.data.type === "DIRECTOR" &&
                  user.data.app_approve_discount === false
                    ? true
                    : false
                }
              />
            </div>
          )}
        </div>
        {onReject && (
          <div>
            <div className="mt-3">
              <label htmlFor="notes">
                Notes<span style={{ color: "red" }}>*</span>
              </label>
              <textarea
                name="notes"
                className={`form-control ${
                  noteReject.length < 5 && "is-invalid"
                }`}
                id="notes"
                value={noteReject}
                onChange={(e) => setNoteReject(e.target.value)}
              />
            </div>
            <div className="mt-3 mb-3" onClick={() => sendRejection()}>
              <Button
                title={"Reject"}
                btnStyle={"btn-danger"}
                btnWidth={"100%"}
                disabled={noteReject.length < 5 ? true : false}
              />
            </div>
          </div>
        )}
      </div>

      <Popup setPopup={setEditDiscountPopup} popup={editDiscountPopup}>
        <EditDiscount
          order={data ? data : ""}
          setAdditionalDiscount={setAdditionalDiscount}
          additionalDiscount={additionalDiscount}
          preview={preview}
          user={user}
          priceDiscount={priceDiscount}
          setEditDiscountPopup={setEditDiscountPopup}
          editDiscountPopup={editDiscountPopup}
          refresh={refresh}
          setRefresh={setRefresh}
        />
      </Popup>
    </div>
  );
};

const mapStateToProps = (state) => ({
  auth: state.auth,
});

export default connect(mapStateToProps)(ApprovalDetail);
