import axios from "axios";
import moment from "moment";
import React, { useState } from "react";
import { useParams, useHistory } from "react-router-dom";

import { connect } from "react-redux";
import { isValidate } from "../../../lib/Validate";
import { mainUrl } from "../../../api/api";
import LoadingTableAllData from "../../Loaded/LoadingTableAllData";
import Header from "./ReportLeadsHead";
import Activity from "../../ActivityDetail/Activity";
import Button from "../../Button/Button";
import useReportLeadsStatusList from "../apiReportLeads/useReportLeadsStatusList";
import ReportLeadsHeader from "./ReportLeadsHeader";
const ReportLeadsStatus = ({ReportLeadFilterRedux: {channelId, companyId, brandId, currentChannel, startEndDate, userType}}) => {
  const params = useParams();
  const history = useHistory();
  const historyState = history?.location?.state;
  const { user_id, detail_type } = params;
  const [activityDetail, setActivityDetail] = useState(false);
  const [customerActivity, setCustomerActivity] = useState(null);
  const [orderId, setOrderId] = useState(null);
 
    const [searchState, setSearchState] = useState({
      start: startEndDate.start,
      end: startEndDate.end,
      channelId: channelId === null ? "" : channelId,
      companyId: companyId === null ? "" : companyId,
      brandId: brandId === null ? "" : brandId,
      userType: userType, 
      currentUserType: "",
      userId: user_id,
      status: detail_type,
      count: 1
  });
 
    const { data:reportDataStatus, error, isLoading } = useReportLeadsStatusList({searchState});
    console.log(isLoading, "check loading yah", searchState)
    const handleClickDetail = async (activity) => {
    
    try {
      const res = await axios.get(
        `${mainUrl}/activities?filter[id]=${activity?.latest_activity?.id}`,
        {
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${localStorage.token}`,
          },
        }
      );
      setCustomerActivity(res.data.data[0]);
    } catch (error) {
      console.error(error);
    }
    setActivityDetail(!activityDetail);
    // setCustomerActivity(activity);
    setOrderId(activity.order ? activity.order.id : null);
  };
  
  if(isLoading){
    return <div className="">
              <Header
                icon=""
                title={`Report Leads - ${detail_type.toUpperCase()}`}
                back={true}
                user={false}
              />
              <ReportLeadsHeader 
                  searchState={searchState}
                  setSearchState={setSearchState}
                  type="company"
                  channel={false}
                  company={false}
              />
              <LoadingTableAllData />        
            </div>
  }

  if(error){
    return <h4>Terjadi kesalahan pada server</h4>
  }

  return (
    <div>
      <Header
        icon=""
        title={`Report Leads - ${detail_type.toUpperCase()}`}
        back={true}
        user={false}
      />

        <ReportLeadsHeader 
            searchState={searchState}
            setSearchState={setSearchState}
            user={historyState?.user ?? null}
            channel={false}
            company={false}
            type="type"
        />
      <div style={{ overflow: "scroll" }}>
          <table className="" style={{ margin: "10px 0" }}>
            <thead>
              <tr>
                <th>No.</th>
                <th>Date</th>
                <th>Lead</th>
                {detail_type === "hot" && <th>Invoice Number</th>}
                <th>Follow Up</th>
                <th>Store Location</th>
                {detail_type === "hot" && <th>Payment</th>}
                {detail_type === "hot" && <th>Quotation</th>}
                <th>Sales</th>
                <th>Status</th>
                <th>Action</th>
              </tr>
            </thead>
            <tbody>
              {reportDataStatus &&
                reportDataStatus?.data?.map((activity, idx) => {
                  return (
                    <tr key={activity.id}>
                      <td>{reportDataStatus?.meta?.from + idx}</td>
                      <td>
                        {!isValidate(activity?.created_at)
                          ? moment(activity?.created_at).format(
                              "MM/DD/YYYY"
                            )
                          : ""}
                      </td>
                      <td>
                        {!isValidate(activity.label)
                          ? `${activity.label}`
                          : ""}
                      </td>
                      {detail_type === "hot" && (
                        <td>
                          {!isValidate(activity.order)
                            ? activity.order.invoice_number
                            : ""}
                        </td>
                      )}

                      <td>
                        {!isValidate(activity?.latest_activity?.follow_up_method)
                          ? activity.latest_activity?.follow_up_method + ""
                          : ""}
                      </td>
                      <td>
                        {!isValidate(activity.channel.name)
                          ? activity.channel.name
                          : ""}
                      </td>
                      {detail_type === "hot" && (
                        <td>
                          {!isValidate(activity.order)
                            ? activity.order.payment_status
                            : ""}
                        </td>
                      )}
                      {detail_type === "hot" && (
                        <td>
                          {!isValidate(activity.order)
                            ? activity.order.status
                            : ""}
                        </td>
                      )}

                      <td>
                        {!isValidate(activity.user.name)
                          ? activity.user.name
                          : ""}
                      </td>
                      <td>
                        {!isValidate(activity.status) ? activity.status : ""}
                      </td>
                      <td>
                        <div
                          onClick={() => handleClickDetail(activity)}
                          className="activity-detail-btn"
                        >
                          <img
                            src="/Asset/Action Icon/eye.png"
                            style={{ marginRight: "5px" }}
                            alt="eye"
                          />
                          See Detail
                        </div>
                      </td>
                    </tr>
                  );
                })}
            </tbody>
          </table>
          <div style={{display:"flex", gap:"20px", marginTop:"50px", alignItems:"center"}}>
          <div style={{display: reportDataStatus?.links?.prev === null ? "none" : "block"}}>
          <Button
                onClick={(e) => setSearchState((prev) => ({
                    ...prev,
                    count: prev.count === 1 ? 1 : prev.count - 1
                }))}
                icon=""
                title={"Prev"}
                style={{ width: "11rem!important"}}
                btnStyle={"primary-btn"}
              />
              </div>
              
              <div style={{display: reportDataStatus?.links?.next === null ? "none" : "block"}}>
               <Button
                onClick={(e) => {setSearchState((prev) => ({
                    ...prev,
                    count: prev.count + 1
                }))}}
                icon=""
                title={"Next"}
                style={{ width: "11rem!important", display: reportDataStatus?.links?.next === null ? "none" : "block"}}
                btnStyle={"primary-btn"}
              />
              </div>
        </div>
        </div>
      {customerActivity ? (
        <Activity
          activityDetail={activityDetail}
          setActivityDetail={setActivityDetail}
          customerActivity={customerActivity}
          orderId={orderId}
        />
      ) : (
        ""
      )}
    </div>
  );
};
const mapStateToProps = (state) => ({
  auth: state.auth,
  target: state.target,
  prosesData: state.prosesData,
  ReportLeadFilterRedux: state.ReportLeadFilterRedux,
});
export default connect(mapStateToProps)(ReportLeadsStatus);
